/// A CAS entry: (key, old_value, old_kind, new_value, new_kind).
pub type CasEntry = (Vec<u8>, Vec<u8>, KvKind, Vec<u8>, KvKind);

/// Versioned CAS entry: `(user_key, ts, old_value, old_kind, new_value, new_kind)`.
pub type VersionedCasEntry = (Vec<u8>, u64, Vec<u8>, KvKind, Vec<u8>, KvKind);

/// Lookup result: `(value, kind, found_internal_key, version_ts, expire_at_secs)`.
/// `version_ts` is the MVCC timestamp of the found version (0 when MVCC disabled).
/// `expire_at_secs` is the TTL expiration timestamp (None for non-TTL entries).
type LookupResult = (Option<Bytes>, KvKind, Bytes, u64, Option<u64>);
type VersionedCasCandidate = Option<(Vec<u8>, u32)>;

/// Only a direct batch reservation may defer to the async quota coordinator.
/// Rotation and seal failures remain errors, even when their cause is spool pressure.
pub(crate) enum MvccWriteBatchOutcome {
    Complete,
    SourceSpoolWait {
        generation: u64,
        error: anyhow::Error,
    },
}

impl MvccWriteBatchOutcome {
    pub(crate) fn into_result(self) -> Result<()> {
        match self {
            Self::Complete => Ok(()),
            Self::SourceSpoolWait { error, .. } => Err(error),
        }
    }
}

#[cfg(target_os = "linux")]
#[must_use = "install only after durable SealStarted and retain all reservations through reclamation"]
pub(crate) struct PreparedV7PitrSeal<'guard> {
    seal: crate::pitr::seal::V7Seal,
    wal_path: PathBuf,
    seal_path: PathBuf,
    bytes: Vec<u8>,
    reservation: Option<crate::wal::v7::admission::WalV7OwnedPreparationReservation>,
    successor_segment_id: u64,
    retained_resources: Arc<crate::wal::v7::admission::WalV7RetainedResources>,
    successor_reservation: Option<crate::wal::v7::admission::WalV7SuccessorReservation>,
    installed: bool,
    _lifecycle_guards: std::marker::PhantomData<&'guard ()>,
}

#[cfg(target_os = "linux")]
impl PreparedV7PitrSeal<'_> {
    pub(crate) fn boundary(&self) -> crate::pitr::manifest::ImmutableBoundary {
        self.seal.boundary
    }

    pub(crate) fn encoded_bytes(&self) -> &[u8] {
        &self.bytes
    }

    pub(crate) fn into_installed(
        mut self,
    ) -> Result<(
        crate::pitr::seal::V7Seal,
        PathBuf,
        PathBuf,
        crate::wal::v7::admission::WalV7OwnedPreparationReservation,
    )> {
        ensure!(self.installed, "v7 PITR seal sidecar was not installed");
        let reservation = self
            .reservation
            .take()
            .ok_or_else(|| anyhow!("v7 PITR seal reservation is missing"))?;
        Ok((self.seal, self.wal_path, self.seal_path, reservation))
    }

    fn retain_reservation_for_possible_sidecar(&mut self) -> Result<()> {
        if let Some(reservation) = self.reservation.take() {
            self.retained_resources
                .retain_preparation_reservation(self.seal.header.segment_id.0, reservation)?;
        }

        Ok(())
    }
}

