    #[test]
    fn pitr_interrupted_enable_promotes_the_installed_successor() {
        // The crash window between installing the segment-0 successor and
        // persisting `EnableComplete`. Reopening must adopt the successor's
        // memtable as the active one: `resume_pitr` decides whether a successor
        // still has to be installed from `uses_wal_v5()`, so an engine that fell
        // back to the empty placeholder would install a second one.
        let dir = tempdir().unwrap();
        let options = LsmStorageOptions {
            enable_wal: true,
            ..LsmStorageOptions::default_for_test()
        };
        let engine = KvEngine::open(&dir, options.clone()).unwrap();
        let mut coordinator = crate::pitr::enable::PitrEnableCoordinator::default();
        coordinator
            .begin_enable_with_identities(
                crate::pitr::enable::PitrEnableRequest {
                    repository_id: [1; 16],
                    config: crate::pitr::manifest::PersistedPitrConfig {
                        archive_interval_ms: 1000,
                        max_segment_bytes: 8192,
                        max_unarchived_bytes: 8192,
                        max_source_spool_bytes: 16384,
                    },
                },
                [2; 16],
                [3; 16],
            )
            .unwrap();
        engine
            .persist_pitr_lifecycle(coordinator.records(), coordinator.state().clone())
            .unwrap();
        engine
            .inner
            .install_pitr_v5_successor(
                crate::pitr::WalV5Header {
                    wal_format_version: crate::pitr::WAL_V5_VERSION,
                    timeline_id: crate::pitr::TimelineId([2; 16]),
                    archive_epoch_id: crate::pitr::ArchiveEpochId([3; 16]),
                    segment_id: crate::pitr::SegmentId(0),
                    predecessor: crate::pitr::ChainAnchor::Genesis {
                        archive_epoch_id: crate::pitr::ArchiveEpochId([3; 16]),
                    },
                },
                &engine.inner.state_lock.lock(),
            )
            .unwrap();
        // An interrupted enable is not durably closable from the layer that added
        // the PITR-aware close onward; dropping releases the storage either way.
        drop(engine);

        let reopened = KvEngine::open(&dir, options).unwrap();
        assert!(
            reopened.inner.state.load().memtable.uses_wal_v5(),
            "the successor installed before the interruption must be the active memtable"
        );
        assert!(reopened.put(b"blocked", b"write").is_err());
        drop(reopened);
    }

    /// An archive interval long enough that the background maintenance timer
    /// cannot fire during a test's write loop.
    ///
    /// That task closes commit admission for a bounded pause while it seals a
    /// segment, and a write landing inside the pause comes back as an error
    /// rather than waiting for it to reopen. With the usual one-second interval
    /// a long write loop crosses that boundary once the machine is slow or loaded
    /// enough, failing a write that has nothing to do with what these tests
    /// cover, so they run with the timer effectively out of the way.
    #[cfg(target_os = "linux")]
    const PITR_TEST_ARCHIVE_INTERVAL: std::time::Duration = std::time::Duration::from_secs(3600);

    #[cfg(target_os = "linux")]
    fn enable_pitr_for_test(
        engine: &KvEngine,
        repository: &std::path::Path,
        archive_interval: std::time::Duration,
    ) {
        let outcome = engine
            .enable_pitr(crate::pitr::api::PitrOptions {
                repository: repository.to_path_buf(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval,
                    max_segment_bytes: 64 * 1024 * 1024,
                    max_unarchived_bytes: 256 * 1024 * 1024,
                    max_source_spool_bytes: 256 * 1024 * 1024,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        // Some outcomes are reported as `Ok` on purpose: an uncertain manifest
        // publication leaves commit admission stopped, so the epoch cannot take
        // writes it can no longer archive, and only a reopen settles it. A test
        // that carried on would fail later with a barrier error instead of
        // saying what actually went wrong.
        assert!(
            matches!(outcome, crate::pitr::api::EnablePitrOutcome::Enabled { .. }),
            "enable_pitr did not reach Enabled: {outcome:?}"
        );
    }

    #[cfg(target_os = "linux")]
    fn v7_recovery_test_database(directory: &std::path::Path) -> anyhow::Result<LsmStorageOptions> {
        v7_recovery_test_database_with_segment_limit(directory, 1 << 20)
    }

    /// Keep periodic target rotation and reconciliation from consuming the
    /// boundary a test deliberately drives through capacity retry or resume.
    #[cfg(target_os = "linux")]
    fn suspend_pitr_maintenance_for_test(engine: &KvEngine) {
        engine
            .inner
            .pitr_maintenance_queued
            .store(true, std::sync::atomic::Ordering::Release);
    }

    #[cfg(target_os = "linux")]
    fn v7_recovery_test_database_with_segment_limit(
        directory: &std::path::Path,
        max_segment_bytes: u64,
    ) -> anyhow::Result<LsmStorageOptions> {
        v7_recovery_test_database_with_segment_limit_and_interval(
            directory,
            max_segment_bytes,
            std::time::Duration::from_secs(3600),
        )
        .map(|(options, _)| options)
    }

    #[cfg(target_os = "linux")]
    fn v7_recovery_test_database_with_segment_limit_and_interval(
        directory: &std::path::Path,
        max_segment_bytes: u64,
        archive_interval: std::time::Duration,
    ) -> anyhow::Result<(LsmStorageOptions, u64)> {
        let engine = pitr_flush_test_engine_with_segment_limit_and_interval(
            directory,
            max_segment_bytes,
            archive_interval,
        );
        let state = engine.pitr_manifest_state.lock().clone();
        assert!(state.obligations.is_empty());
        let source_segment_id = state
            .active_segment_id
            .ok_or_else(|| anyhow::anyhow!("v7 fixture has no Active segment"))?;
        engine.close_storage()?;
        drop(engine);

        Ok((
            install_v7_recovery_test_database(directory, state)?,
            source_segment_id,
        ))
    }

    #[cfg(target_os = "linux")]
    fn install_v7_recovery_test_database(
        directory: &std::path::Path,
        state: crate::pitr::manifest::PitrState,
    ) -> anyhow::Result<LsmStorageOptions> {
        use crate::{
            pitr::{
                ArchiveEpochId, LIVE_WAL_V5_LIMITS, RecordedAt, SegmentId, TimelineId, WalBatch,
                WalEntry,
                manifest::{ActiveBoundary, PitrManifestRecord},
            },
            wal::v7::{
                admission::{WalV7ReservationOwner, WalV7ResourceLedger, WalV7ResourceLimits},
                codec::{WAL_V7_HEADER_LEN, WalV7Header, encode_generation_zero_frontier},
                install::recover_and_install_active,
                leader::WalV7LeaderWriter,
                recovery::WalV7RecoveryAuthority,
            },
        };

        let database = directory.join("db");
        let _open_lock = super::WalV7OpenLock::acquire(&database)?;
        let header = WalV7Header {
            timeline_id: TimelineId(state.timeline_id.unwrap()),
            archive_epoch_id: ArchiveEpochId(state.archive_epoch_id.unwrap()),
            segment_id: SegmentId(state.active_segment_id.unwrap()),
            predecessor: super::pitr_chain_anchor_from_persisted(state.predecessor_anchor.unwrap()),
            incarnation: [7; 16],
        };
        let wal_path = database.join(format!("pitr-{:020}.wal", header.segment_id.0));
        let mut image = header.encode()?.to_vec();
        image.extend_from_slice(&encode_generation_zero_frontier(header.digest()?)?);
        std::fs::write(&wal_path, image)?;
        let empty = ActiveBoundary {
            timeline_id: header.timeline_id.0,
            archive_epoch_id: header.archive_epoch_id.0,
            segment_id: header.segment_id.0,
            incarnation: header.incarnation,
            ticket_end: 0,
            durable_end: WAL_V7_HEADER_LEN as u64,
            last_commit_ts: 0,
            prefix_digest: header.digest()?,
        };
        let installed = recover_and_install_active(
            &wal_path,
            WalV7RecoveryAuthority::Active {
                predecessor: header.predecessor,
                durable_anchors: vec![empty],
            },
        )?
        .installed;
        let ledger = WalV7ResourceLedger::new(WalV7ResourceLimits {
            max_logical_wal_bytes: u64::MAX,
            max_source_spool_bytes: u64::MAX,
            max_recovery_workspace_bytes: u64::MAX,
            max_buffer_memory_bytes: u64::MAX,
            max_seal_index_bytes: u64::MAX,
        })?;
        let owner = Arc::new(WalV7ReservationOwner::new(ledger, &installed)?);
        let mut writer = WalV7LeaderWriter::new(
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&wal_path)?,
            std::fs::File::open(&wal_path)?,
            installed.runtime_seed()?,
            state.config.as_ref().unwrap().max_segment_bytes,
            owner,
        )?;
        let frontier = writer
            .append_batch(
                &WalBatch {
                    commit_ts: 7,
                    recorded_at: RecordedAt {
                        secs: 4_000_000_000,
                        nanos: 0,
                    },
                    entries: vec![WalEntry::Put {
                        key: b"v7-key".to_vec(),
                        value: vec![crate::vlog::KvKind::Inline as u8, b'v'],
                    }],
                },
                LIVE_WAL_V5_LIMITS,
            )?
            .frontier
            .frontier;
        drop(writer);
        let manifest = crate::manifest::Manifest::recover(database.join("MANIFEST"))?.0;
        manifest.add_records_when_init(&[
            crate::manifest::ManifestRecord::Pitr(PitrManifestRecord::ActiveBoundaryAdvanced {
                boundary: empty,
            }),
            crate::manifest::ManifestRecord::Pitr(PitrManifestRecord::ActiveBoundaryAdvanced {
                boundary: ActiveBoundary {
                    ticket_end: frontier.ticket_end,
                    durable_end: frontier.durable_end,
                    last_commit_ts: frontier.last_commit_ts,
                    prefix_digest: frontier.prefix_digest,
                    ..empty
                },
            }),
        ])?;

        Ok(LsmStorageOptions {
            enable_wal: true,
            pitr_repository: Some(directory.join("repository")),
            ..LsmStorageOptions::default_for_test()
        })
    }

    /// Model a crash after SegmentSealed and the successor's empty boundary
    /// became durable, with the source memtable still awaiting its Flush record.
    #[cfg(target_os = "linux")]
    fn v7_sealed_recovery_test_database(
        directory: &std::path::Path,
    ) -> anyhow::Result<(LsmStorageOptions, std::path::PathBuf)> {
        v7_recovery_point_transition_test_database(directory, false, true, true, true)
    }

    #[cfg(target_os = "linux")]
    fn v7_sealed_recovery_test_database_with_legacy_interstitial(
        directory: &std::path::Path,
        legacy_interstitial: bool,
    ) -> anyhow::Result<(LsmStorageOptions, std::path::PathBuf)> {
        v7_recovery_point_transition_test_database(directory, legacy_interstitial, true, true, true)
    }

    #[cfg(target_os = "linux")]
    fn v7_recovery_point_transition_test_database(
        directory: &std::path::Path,
        legacy_interstitial: bool,
        segment_sealed: bool,
        successor_installed: bool,
        sidecar_installed: bool,
    ) -> anyhow::Result<(LsmStorageOptions, std::path::PathBuf)> {
        use sha2::Digest;

        use crate::{
            manifest::ManifestRecord,
            pitr::{
                ChainAnchor, CommitTimeHighWater, SegmentAnchor, SegmentId,
                manifest::{
                    ActiveBoundary, PersistedChainAnchor, PersistedCommitAnchor,
                    PersistedRecordedAt, PitrManifestRecord,
                },
            },
            wal::v7::codec::{WAL_V7_HEADER_LEN, WalV7Header},
        };

        let mut options = v7_recovery_test_database(directory)?;
        let database = directory.join("db");
        let engine = KvEngine::open(&database, options.clone())?;
        engine.sync()?;
        let state = engine.pitr_manifest_state.lock().clone();
        let source_wal = engine
            .inner
            .state
            .load()
            .memtable
            .wal_path()
            .unwrap()
            .to_path_buf();
        let successor_memtable_id = engine.inner.next_sst_id();
        engine.close_storage()?;
        drop(engine);

        let source_bytes = std::fs::read(&source_wal)?;
        let header = WalV7Header::decode(&source_bytes[..WAL_V7_HEADER_LEN])?;
        let (seal, seal_bytes) = crate::pitr::seal::build_v7_seal(
            &source_bytes,
            state.active_boundary.unwrap(),
            header.predecessor,
        )?;
        if sidecar_installed {
            std::fs::write(source_wal.with_extension("seal"), &seal_bytes)?;
        }
        let seal_digest = sha2::Sha256::digest(&seal_bytes).into();
        let successor_header = WalV7Header {
            segment_id: SegmentId(state.next_segment_id),
            incarnation: [9; 16],
            predecessor: ChainAnchor::Segment(SegmentAnchor {
                segment_id: header.segment_id,
                wal_digest: seal.boundary.wal_digest,
                seal_digest,
            }),
            ..header
        };
        if successor_installed {
            crate::wal::v7::install::create_empty_active_image(
                database.join(format!("pitr-{:020}.wal", state.next_segment_id)),
                successor_header,
            )?;
        }
        let last = seal.entries.last().unwrap();
        let recorded_at = PersistedRecordedAt {
            secs: last.recorded_at.secs,
            nanos: last.recorded_at.nanos,
        };
        let successor_active_boundary = ActiveBoundary {
            timeline_id: successor_header.timeline_id.0,
            archive_epoch_id: successor_header.archive_epoch_id.0,
            segment_id: successor_header.segment_id.0,
            incarnation: successor_header.incarnation,
            ticket_end: 0,
            durable_end: WAL_V7_HEADER_LEN as u64,
            last_commit_ts: 0,
            prefix_digest: successor_header.digest()?,
        };
        let mut records = vec![ManifestRecord::Pitr(PitrManifestRecord::SealStarted {
            segment_id: header.segment_id.0,
            successor_segment_id: state.next_segment_id,
            logical_length: seal.boundary.sealed_end,
            immutable_boundary: Some(seal.boundary),
        })];
        if segment_sealed {
            anyhow::ensure!(
                sidecar_installed,
                "sealed fixture requires its source sidecar"
            );
            if successor_installed {
                records.push(ManifestRecord::NewPitrMemtable {
                    id: successor_memtable_id,
                    segment_id: state.next_segment_id,
                });
            }
            records.push(ManifestRecord::Pitr(PitrManifestRecord::SegmentSealed {
                segment_id: header.segment_id.0,
                segment_anchor: PersistedChainAnchor::Segment {
                    segment_id: header.segment_id.0,
                    wal_digest: seal.boundary.wal_digest,
                    seal_digest,
                },
                last_recorded_at: Some(recorded_at),
                last_commit_anchor: Some(PersistedCommitAnchor {
                    segment_id: header.segment_id.0,
                    commit_ts: last.commit_ts,
                    recorded_at,
                    entry_digest: crate::pitr::commit_time_entry_digest(CommitTimeHighWater {
                        archive_epoch_id: header.archive_epoch_id,
                        segment_id: header.segment_id,
                        commit_ts: last.commit_ts,
                        recorded_at: last.recorded_at,
                        entry_digest: [0; 32],
                    }),
                }),
                successor_active_boundary: (!legacy_interstitial)
                    .then_some(successor_active_boundary),
            }));
        }
        anyhow::ensure!(
            !legacy_interstitial || (segment_sealed && successor_installed),
            "legacy interstitial fixture requires a sealed installed successor"
        );
        if legacy_interstitial {
            records.extend([
                ManifestRecord::Pitr(PitrManifestRecord::SegmentArchived {
                    segment_id: header.segment_id.0,
                }),
                ManifestRecord::Pitr(PitrManifestRecord::SegmentReclaimable {
                    segment_id: header.segment_id.0,
                }),
                ManifestRecord::Pitr(PitrManifestRecord::SegmentReclaimed {
                    segment_id: header.segment_id.0,
                }),
                ManifestRecord::Pitr(PitrManifestRecord::ActiveBoundaryAdvanced {
                    boundary: successor_active_boundary,
                }),
            ]);
        }
        crate::manifest::Manifest::recover(database.join("MANIFEST"))?
            .0
            .add_records_when_init(&records)?;
        if legacy_interstitial {
            let manifest_path = database.join("MANIFEST");
            let (manifest, mut persisted_records) =
                crate::manifest::Manifest::recover(&manifest_path)?;
            drop(manifest);
            for record in &mut persisted_records {
                match record {
                    ManifestRecord::FormatVersion(version)
                        if *version == crate::manifest::MANIFEST_FORMAT_VERSION =>
                    {
                        *version = 8;
                    }
                    ManifestRecord::Snapshot { format_version, .. }
                        if *format_version == crate::manifest::MANIFEST_FORMAT_VERSION =>
                    {
                        *format_version = 8;
                    }
                    _ => {}
                }
            }
            let mut bytes = Vec::new();
            for record in persisted_records {
                serde_json::to_writer(&mut bytes, &record)?;
            }
            std::fs::write(manifest_path, bytes)?;
        }
        // Exercise restart replay before repository resume can archive and
        // reclaim the source whose on-disk state the test is inspecting.
        options.pitr_repository = None;

        Ok((options, source_wal))
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v8_manifest_replays_cleanup_between_legacy_seal_and_boundary() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let (options, source_wal) =
            v7_sealed_recovery_test_database_with_legacy_interstitial(directory.path(), true)?;
        let database = directory.path().join("db");
        std::fs::remove_file(&source_wal)?;
        std::fs::remove_file(source_wal.with_extension("seal"))?;

        let engine = KvEngine::open(&database, options)?;
        let recovered = engine.inner.pitr_state.lock().clone();
        let boundary = recovered.active_boundary.unwrap();
        assert_eq!(boundary.segment_id, recovered.active_segment_id.unwrap());
        assert_eq!(boundary.ticket_end, 0);
        assert_eq!(
            boundary.durable_end,
            crate::wal::v7::codec::WAL_V7_HEADER_LEN as u64
        );
        assert!(!recovered.obligations.contains_key(&1));
        assert!(!recovered.legacy_v7_boundary_recovery);
        engine.close()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v8_reclaimed_v7_successor_requires_its_v7_wal() -> anyhow::Result<()> {
        use crate::{
            manifest::{Manifest, ManifestRecord},
            pitr::manifest::PitrManifestRecord,
            wal::v7::codec::WalV7Header,
        };

        for format_version in [
            Some(crate::wal::format::WAL_FORMAT_VERSION_V7),
            Some(crate::pitr::WAL_V5_VERSION_LEGACY),
            Some(crate::pitr::WAL_V5_VERSION),
            None,
        ] {
            let directory = tempdir()?;
            let (options, source_wal) =
                v7_sealed_recovery_test_database_with_legacy_interstitial(directory.path(), true)?;
            let database = directory.path().join("db");
            let manifest_path = database.join("MANIFEST");
            let (manifest, mut records) = Manifest::recover(&manifest_path)?;
            drop(manifest);
            let Some(ManifestRecord::Pitr(PitrManifestRecord::ActiveBoundaryAdvanced { boundary })) =
                records.pop()
            else {
                anyhow::bail!("fixture is missing the successor boundary record");
            };
            // The legacy stream ends after reclamation, before its separate
            // successor boundary record. Replay must retain its v7 authority.
            let mut bytes = Vec::new();
            for record in records {
                serde_json::to_writer(&mut bytes, &record)?;
            }
            std::fs::write(&manifest_path, &bytes)?;
            std::fs::remove_file(&source_wal)?;
            std::fs::remove_file(source_wal.with_extension("seal"))?;

            let wal_path = database.join(format!("pitr-{:020}.wal", boundary.segment_id));
            let header = WalV7Header::decode(&std::fs::read(&wal_path)?)?;
            match format_version {
                Some(version) if version == crate::wal::format::WAL_FORMAT_VERSION_V7 => {}
                Some(version) => {
                    let replacement =
                        crate::pitr::encode_v5_file_header(crate::pitr::WalV5Header {
                            wal_format_version: version,
                            timeline_id: header.timeline_id,
                            archive_epoch_id: header.archive_epoch_id,
                            segment_id: header.segment_id,
                            predecessor: header.predecessor,
                        })?;
                    std::fs::write(&wal_path, replacement)?;
                }
                None => std::fs::remove_file(&wal_path)?,
            }
            let wal_before = wal_path
                .try_exists()?
                .then(|| std::fs::read(&wal_path))
                .transpose()?;
            let opened = KvEngine::open(&database, options);
            if format_version == Some(crate::wal::format::WAL_FORMAT_VERSION_V7) {
                let engine = opened?;
                let recovered = engine.inner.pitr_state.lock().clone();
                assert_eq!(recovered.active_boundary, Some(boundary));
                assert!(recovered.obligations.is_empty());
                assert!(!recovered.legacy_v7_boundary_recovery);
                engine.close_storage()?;
            } else {
                if let Ok(engine) = &opened {
                    engine.close_storage()?;
                }
                assert!(
                    opened.is_err(),
                    "accepted replacement format {format_version:?} for a known v7 successor"
                );
                let error = opened.err().unwrap();
                assert!(format!("{error:#}").contains(
                    "legacy v7 Active boundary has not been verified against its WAL header"
                ));
                assert_eq!(std::fs::read(&manifest_path)?, bytes);
                assert_eq!(
                    wal_path
                        .try_exists()?
                        .then(|| std::fs::read(&wal_path))
                        .transpose()?,
                    wal_before
                );
            }
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v8_global_snapshot_recovers_the_empty_v7_successor_boundary() -> anyhow::Result<()> {
        use crate::manifest::ManifestRecord;

        let directory = tempdir()?;
        let (options, _) = v7_sealed_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open(&database, options.clone())?;
        let current_pitr = engine.inner.pitr_state.lock().clone();
        let active_segment_id = current_pitr.active_segment_id.unwrap();
        assert!(current_pitr.active_boundary.is_some());

        let state = engine.inner.state.load();
        let mut imm_memtable_ids = state
            .imm_memtables
            .iter()
            .filter(|memtable| memtable.wal_path().is_some())
            .map(|memtable| memtable.id())
            .collect::<Vec<_>>();
        if state.memtable.wal_path().is_some() {
            imm_memtable_ids.push(state.memtable.id());
        }
        imm_memtable_ids.sort_unstable();
        imm_memtable_ids.dedup();
        let pitr_memtable_segments = LsmStorageInner::snapshot_pitr_memtable_segments(
            state
                .imm_memtables
                .iter()
                .map(|memtable| memtable.as_ref())
                .chain(std::iter::once(state.memtable.as_ref())),
        );
        let mut legacy_pitr_state = current_pitr;
        legacy_pitr_state.active_boundary = None;
        let snapshot = ManifestRecord::Snapshot {
            l0_sstables: state.l0_sstables.clone(),
            levels: state.levels.clone(),
            range_only_ssts: state.range_only_ssts.clone(),
            next_sst_id: engine
                .inner
                .next_sst_id
                .load(std::sync::atomic::Ordering::Acquire),
            vlog_references: Vec::new(),
            imm_memtable_ids,
            pitr_memtable_segments,
            active_compaction_filters: Vec::new(),
            next_compaction_filter_id: 0,
            format_version: 8,
            immutable_file_metadata: state.immutable_file_metadata.clone(),
            pitr_state: Some(legacy_pitr_state),
        };
        drop(state);
        engine.close()?;
        engine.inner.manifest.as_ref().unwrap().snapshot(snapshot)?;
        drop(engine);

        let reopened = KvEngine::open(&database, options)?;
        let recovered = reopened.inner.pitr_state.lock().clone();
        let boundary = recovered.active_boundary.unwrap();
        assert_eq!(boundary.segment_id, active_segment_id);
        assert_eq!(boundary.ticket_end, 0);
        assert_eq!(
            boundary.durable_end,
            crate::wal::v7::codec::WAL_V7_HEADER_LEN as u64
        );
        assert!(!recovered.legacy_v7_boundary_recovery);
        drop(reopened);

        let persisted_snapshot: ManifestRecord =
            serde_json::from_slice(&std::fs::read(database.join("ENGINE_MANIFEST"))?)?;
        assert!(matches!(
            persisted_snapshot,
            ManifestRecord::Snapshot {
                format_version: crate::manifest::MANIFEST_FORMAT_VERSION,
                pitr_state: Some(state),
                ..
            } if state.active_boundary == Some(boundary)
        ));

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealing_recovery_resumes_after_seal_started() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let (options, source_wal) = v7_recovery_point_transition_test_database(
            directory.path(),
            false,
            false,
            false,
            false,
        )?;
        let database = directory.path().join("db");
        assert!(!source_wal.with_extension("seal").exists());
        assert!(
            !database.join(format!("pitr-{:020}.wal", 1)).exists(),
            "fixture unexpectedly installed the v7 successor"
        );

        let engine = KvEngine::open(&database, options)?;
        assert_eq!(
            LsmStorageInner::pitr_segment_of(engine.inner.state.load().memtable.as_ref()),
            Some(0)
        );
        assert!(matches!(
            engine.resume_pitr(directory.path().join("repository"))?,
            crate::pitr::api::PitrResumeOutcome::Resumed
        ));
        assert_eq!(
            LsmStorageInner::pitr_segment_of(engine.inner.state.load().memtable.as_ref()),
            Some(1)
        );
        let retained = engine
            .inner
            .state
            .load()
            .memtable
            .wal_v7_reservation_owner()
            .and_then(|owner| owner.retained_resources())
            .ok_or_else(|| anyhow::anyhow!("successor has no retained v7 resource ledger"))?;
        assert_eq!(retained.ledger().snapshot().logical_wal_bytes, 0);
        assert_eq!(engine.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        engine.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealed_recovery_recreates_missing_successor() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let (options, source_wal) =
            v7_recovery_point_transition_test_database(directory.path(), false, true, false, true)?;
        let database = directory.path().join("db");
        let successor_path = database.join("pitr-00000000000000000001.wal");
        assert!(source_wal.with_extension("seal").exists());
        assert!(!successor_path.exists());

        let engine = KvEngine::open(&database, options)?;
        assert!(successor_path.is_file());
        assert_eq!(
            LsmStorageInner::pitr_segment_of(engine.inner.state.load().memtable.as_ref()),
            Some(1)
        );
        assert_eq!(engine.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert!(matches!(
            engine.resume_pitr(directory.path().join("repository"))?,
            crate::pitr::api::PitrResumeOutcome::Resumed
        ));
        assert_eq!(engine.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        engine.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealed_recovery_recreates_successor_from_legacy_source() -> anyhow::Result<()> {
        use crate::{
            manifest::{Manifest, ManifestRecord},
            pitr::manifest::{
                ActiveBoundary, PersistedChainAnchor, PersistedCommitAnchor, PersistedPitrConfig,
                PersistedRecordedAt, PitrManifestRecord,
            },
            pitr::{
                ArchiveEpochId, ChainAnchor, CommitTimeHighWater, LIVE_WAL_V5_LIMITS, RecordedAt,
                SegmentAnchor, SegmentId, TimelineId, WAL_V5_HEADER_LEN, WalBatch, WalEntry,
                WalV5Header, commit_time_entry_digest, encode_v5_batch, encode_v5_file_header,
                seal::{V5Seal, build_v5_seal},
            },
            wal::v7::codec::{WAL_V7_HEADER_LEN, WalV7Header},
        };
        use sha2::Digest;

        let directory = tempdir()?;
        let database = directory.path().join("db");
        std::fs::create_dir_all(&database)?;
        let options = LsmStorageOptions {
            enable_wal: true,
            ..LsmStorageOptions::default_for_test()
        };
        let timeline_id = [2; 16];
        let archive_epoch_id = [3; 16];
        let first_source_segment_id = 1;
        let source_segment_id = 2;
        let successor_segment_id = 3;
        let legacy_value = vec![b'x'; 60 * 1024];
        let secondary_value = vec![b'y'; 60 * 1024];
        let tertiary_value = vec![b'z'; 60 * 1024];
        let inline_value = |value: &[u8]| {
            let mut encoded = vec![crate::vlog::KvKind::Inline as u8];
            encoded.extend_from_slice(value);
            encoded
        };
        let source_recorded_at = RecordedAt {
            secs: 1_700_000_000,
            nanos: 123,
        };
        let first_source_header = WalV5Header {
            wal_format_version: crate::pitr::WAL_V5_VERSION,
            timeline_id: TimelineId(timeline_id),
            archive_epoch_id: ArchiveEpochId(archive_epoch_id),
            segment_id: SegmentId(first_source_segment_id),
            predecessor: ChainAnchor::Genesis {
                archive_epoch_id: ArchiveEpochId(archive_epoch_id),
            },
        };
        let first_batch = WalBatch {
            commit_ts: 7,
            recorded_at: source_recorded_at,
            entries: vec![WalEntry::Put {
                key: b"first-legacy-key".to_vec(),
                value: vec![crate::vlog::KvKind::Inline as u8, b'a'],
            }],
        };
        let mut first_source_wal = encode_v5_file_header(first_source_header)?.to_vec();
        first_source_wal.extend_from_slice(&encode_v5_batch(&first_batch, LIVE_WAL_V5_LIMITS)?);
        let (first_source_seal, first_source_seal_bytes) = build_v5_seal(&first_source_wal)?;
        let first_source_anchor = SegmentAnchor {
            segment_id: SegmentId(first_source_segment_id),
            wal_digest: first_source_seal.wal_digest,
            seal_digest: sha2::Sha256::digest(&first_source_seal_bytes).into(),
        };
        let source_header = WalV5Header {
            wal_format_version: crate::pitr::WAL_V5_VERSION,
            timeline_id: TimelineId(timeline_id),
            archive_epoch_id: ArchiveEpochId(archive_epoch_id),
            segment_id: SegmentId(source_segment_id),
            predecessor: ChainAnchor::Segment(first_source_anchor),
        };
        let batch = WalBatch {
            commit_ts: 8,
            recorded_at: source_recorded_at,
            entries: vec![
                WalEntry::Put {
                    key: b"legacy-key".to_vec(),
                    value: inline_value(&legacy_value),
                },
                WalEntry::Put {
                    key: b"secondary-key".to_vec(),
                    value: inline_value(&secondary_value),
                },
                WalEntry::Put {
                    key: b"tertiary-key".to_vec(),
                    value: inline_value(&tertiary_value),
                },
            ],
        };
        let mut source_wal = encode_v5_file_header(source_header)?.to_vec();
        source_wal.extend_from_slice(&encode_v5_batch(&batch, LIVE_WAL_V5_LIMITS)?);
        let small_entry_batch = WalBatch {
            commit_ts: 9,
            recorded_at: source_recorded_at,
            entries: (0..16_384_u32)
                .map(|index| WalEntry::PointDelete {
                    key: index.to_be_bytes().to_vec(),
                })
                .collect(),
        };
        source_wal.extend_from_slice(&encode_v5_batch(&small_entry_batch, LIVE_WAL_V5_LIMITS)?);
        assert_eq!(source_wal.len() as u64 % WAL_V5_HEADER_LEN as u64, 0);
        assert!(source_wal.len() > 16 * 1024);
        let (source_seal, source_seal_bytes) = build_v5_seal(&source_wal)?;
        let max_segment_bytes = 16 * 1024_u64;
        let ordinary_buffer_memory_bytes = max_segment_bytes
            .checked_mul(2)
            .ok_or_else(|| anyhow::anyhow!("test buffer limit overflow"))?
            .max(crate::pitr::seal::V7Seal::max_preparation_memory_bytes(
                max_segment_bytes,
            )?);
        // The decoded and canonicalized entry vectors coexist. Even their
        // storage alone exceeds the previous twice-image-size reservation.
        let entry_vectors_minimum_bytes =
            u64::try_from(2 * small_entry_batch.entries.len() * std::mem::size_of::<WalEntry>())?;
        assert!(entry_vectors_minimum_bytes > 2 * source_seal.logical_length);
        let legacy_source_buffer_bytes =
            V5Seal::validation_memory_bytes(source_seal.logical_length)?;
        assert!(
            legacy_source_buffer_bytes > source_seal.logical_length + entry_vectors_minimum_bytes
        );
        assert!(legacy_source_buffer_bytes > ordinary_buffer_memory_bytes);

        let predecessor_anchor = SegmentAnchor {
            segment_id: SegmentId(source_segment_id),
            wal_digest: source_seal.wal_digest,
            seal_digest: sha2::Sha256::digest(&source_seal_bytes).into(),
        };
        let successor_header = WalV7Header {
            timeline_id: TimelineId(timeline_id),
            archive_epoch_id: ArchiveEpochId(archive_epoch_id),
            segment_id: SegmentId(successor_segment_id),
            predecessor: ChainAnchor::Segment(predecessor_anchor),
            incarnation: [8; 16],
        };
        let successor_boundary = ActiveBoundary {
            timeline_id,
            archive_epoch_id,
            segment_id: successor_segment_id,
            incarnation: successor_header.incarnation,
            ticket_end: 0,
            durable_end: WAL_V7_HEADER_LEN as u64,
            last_commit_ts: 0,
            prefix_digest: successor_header.digest()?,
        };
        let recorded_at = PersistedRecordedAt {
            secs: source_recorded_at.secs,
            nanos: source_recorded_at.nanos,
        };
        let max_unarchived_bytes = first_source_seal
            .logical_length
            .checked_sub(WAL_V5_HEADER_LEN as u64)
            .and_then(|bytes| {
                source_seal
                    .logical_length
                    .checked_sub(WAL_V5_HEADER_LEN as u64)
                    .and_then(|source_bytes| bytes.checked_add(source_bytes))
            })
            .ok_or_else(|| anyhow::anyhow!("test legacy payload budget underflow"))?;
        let full_legacy_images = first_source_seal
            .logical_length
            .checked_add(source_seal.logical_length)
            .ok_or_else(|| anyhow::anyhow!("test legacy image length overflow"))?;
        assert!(full_legacy_images > max_unarchived_bytes);
        let manifest_records = [
            ManifestRecord::FormatVersion(crate::manifest::MANIFEST_FORMAT_VERSION),
            ManifestRecord::NewPitrMemtable {
                id: 0,
                segment_id: first_source_segment_id,
            },
            ManifestRecord::NewPitrMemtable {
                id: 1,
                segment_id: source_segment_id,
            },
            ManifestRecord::Pitr(PitrManifestRecord::EnableIntent {
                repository_id: [1; 16],
                timeline_id,
                archive_epoch_id,
                config: PersistedPitrConfig {
                    archive_interval_ms: 1_000,
                    max_segment_bytes,
                    max_unarchived_bytes,
                    max_source_spool_bytes: 1024 * 1024,
                },
            }),
            ManifestRecord::Pitr(PitrManifestRecord::EnableComplete {
                active_segment_id: first_source_segment_id,
            }),
            ManifestRecord::Pitr(PitrManifestRecord::SealStarted {
                segment_id: first_source_segment_id,
                successor_segment_id: source_segment_id,
                logical_length: first_source_seal.logical_length,
                immutable_boundary: None,
            }),
            ManifestRecord::Pitr(PitrManifestRecord::SegmentSealed {
                segment_id: first_source_segment_id,
                segment_anchor: PersistedChainAnchor::Segment {
                    segment_id: first_source_segment_id,
                    wal_digest: first_source_anchor.wal_digest,
                    seal_digest: first_source_anchor.seal_digest,
                },
                last_recorded_at: Some(recorded_at),
                last_commit_anchor: Some(PersistedCommitAnchor {
                    segment_id: first_source_segment_id,
                    commit_ts: first_batch.commit_ts,
                    recorded_at,
                    entry_digest: commit_time_entry_digest(CommitTimeHighWater {
                        archive_epoch_id: ArchiveEpochId(archive_epoch_id),
                        segment_id: SegmentId(first_source_segment_id),
                        commit_ts: first_batch.commit_ts,
                        recorded_at: source_recorded_at,
                        entry_digest: [0; 32],
                    }),
                }),
                successor_active_boundary: None,
            }),
            ManifestRecord::Pitr(PitrManifestRecord::SealStarted {
                segment_id: source_segment_id,
                successor_segment_id,
                logical_length: source_seal.logical_length,
                immutable_boundary: None,
            }),
            ManifestRecord::Pitr(PitrManifestRecord::SegmentSealed {
                segment_id: source_segment_id,
                segment_anchor: PersistedChainAnchor::Segment {
                    segment_id: source_segment_id,
                    wal_digest: predecessor_anchor.wal_digest,
                    seal_digest: predecessor_anchor.seal_digest,
                },
                last_recorded_at: Some(recorded_at),
                last_commit_anchor: Some(PersistedCommitAnchor {
                    segment_id: source_segment_id,
                    commit_ts: small_entry_batch.commit_ts,
                    recorded_at,
                    entry_digest: commit_time_entry_digest(CommitTimeHighWater {
                        archive_epoch_id: ArchiveEpochId(archive_epoch_id),
                        segment_id: SegmentId(source_segment_id),
                        commit_ts: small_entry_batch.commit_ts,
                        recorded_at: crate::pitr::RecordedAt {
                            secs: recorded_at.secs,
                            nanos: recorded_at.nanos,
                        },
                        entry_digest: [0; 32],
                    }),
                }),
                successor_active_boundary: Some(successor_boundary),
            }),
        ];
        let manifest = Manifest::create(database.join("MANIFEST"))?;
        manifest.add_records_when_init(&manifest_records)?;
        drop(manifest);

        std::fs::write(
            database.join(format!("pitr-{first_source_segment_id:020}.wal")),
            first_source_wal,
        )?;
        std::fs::write(
            database.join(format!("pitr-{first_source_segment_id:020}.seal")),
            &first_source_seal_bytes,
        )?;
        std::fs::write(
            database.join(format!("pitr-{source_segment_id:020}.wal")),
            source_wal,
        )?;
        std::fs::write(
            database.join(format!("pitr-{source_segment_id:020}.seal")),
            &source_seal_bytes,
        )?;
        let successor_path = database.join(format!("pitr-{successor_segment_id:020}.wal"));
        assert!(!successor_path.exists());

        let source_seal_path = database.join(format!("pitr-{source_segment_id:020}.seal"));
        let mut oversized_seal = source_seal_bytes.clone();
        oversized_seal.resize(
            usize::try_from(V5Seal::max_encoded_len_for_segment(
                source_seal.logical_length,
            )?)? + 1,
            0,
        );
        std::fs::write(&source_seal_path, oversized_seal)?;
        let manifest_before = std::fs::read(database.join("MANIFEST"))?;
        let error = match KvEngine::open(&database, options.clone()) {
            Ok(engine) => {
                engine.close_storage()?;
                anyhow::bail!("accepted an oversized legacy predecessor seal");
            }
            Err(error) => error,
        };
        assert!(error.to_string().contains("manifest WAL image bound"));
        assert!(!successor_path.exists());
        assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
        std::fs::write(&source_seal_path, &source_seal_bytes)?;

        let engine = KvEngine::open(&database, options.clone())?;
        assert!(successor_path.is_file());
        let installed_header = WalV7Header::decode(&std::fs::read(&successor_path)?)?;
        assert_eq!(installed_header, successor_header);
        assert!(engine.inner.state.load().memtable.uses_v7_wal());
        assert_eq!(
            LsmStorageInner::pitr_segment_of(engine.inner.state.load().memtable.as_ref()),
            Some(successor_segment_id)
        );
        assert_eq!(
            engine.get(b"first-legacy-key")?,
            Some(Bytes::from_static(b"a"))
        );
        assert_eq!(
            engine.get(b"legacy-key")?,
            Some(Bytes::from(legacy_value.clone()))
        );
        assert_eq!(engine.get(&0_u32.to_be_bytes())?, None);
        assert_eq!(
            engine.inner.pitr_state.lock().obligations[&first_source_segment_id].wal_format,
            crate::pitr::manifest::PitrWalFormat::LegacyV5V6
        );
        assert_eq!(
            engine.inner.pitr_state.lock().obligations[&source_segment_id].wal_format,
            crate::pitr::manifest::PitrWalFormat::LegacyV5V6
        );

        // Recreate the in-process crash window after SegmentSealed: the
        // manifest and empty v7 image are durable, but the legacy source is
        // still the current memtable and has no registered v7 successor.
        let mut storage_state = engine.inner.state.load().as_ref().clone();
        let source_index = storage_state
            .imm_memtables
            .iter()
            .position(|memtable| {
                LsmStorageInner::pitr_segment_of(memtable.as_ref()) == Some(source_segment_id)
            })
            .ok_or_else(|| anyhow::anyhow!("sealed legacy source memtable is missing"))?;
        let legacy_source = storage_state.imm_memtables.remove(source_index);
        storage_state.memtable.close_parallel_wal()?;
        storage_state.memtable.retire_wal_ring();
        storage_state.memtable = legacy_source;
        storage_state.imm_memtables.retain(|memtable| {
            LsmStorageInner::pitr_segment_of(memtable.as_ref()) != Some(successor_segment_id)
        });
        engine.inner.state.store(Arc::new(storage_state));
        // Startup recovery has already registered the empty v7 successor. Replace
        // that registration with the coherent pre-handoff snapshot represented by
        // the rewound runtime state before exercising the in-process recovery.
        engine.inner.ensure_manifest_v7()?;

        let migration_state = engine.pitr_manifest_state.lock().clone();
        let config = migration_state.config.as_ref().unwrap();
        *engine.pitr_segments.lock() = Some(
            crate::pitr::segment::PitrSegmentManager::from_recovered_state(
                successor_segment_id,
                migration_state.next_segment_id,
                u64::try_from(WAL_V7_HEADER_LEN + crate::wal::v7::codec::WAL_V7_FRAME_LEN)?,
                config.max_source_spool_bytes,
                &migration_state.obligations,
            )?,
        );
        engine.resume_v7_successor_install(migration_state)?;
        assert!(engine.inner.state.load().memtable.uses_v7_wal());
        assert_eq!(
            LsmStorageInner::pitr_segment_of(engine.inner.state.load().memtable.as_ref()),
            Some(successor_segment_id)
        );
        assert_eq!(
            engine.get(b"legacy-key")?,
            Some(Bytes::from(legacy_value.clone()))
        );
        engine.close_storage()?;
        drop(engine);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(
            reopened.get(b"legacy-key")?,
            Some(Bytes::from(legacy_value))
        );
        reopened.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealed_recovery_rejects_missing_registered_successor() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let (options, source_wal) = v7_sealed_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let successor_path = database.join("pitr-00000000000000000001.wal");
        std::fs::remove_file(&successor_path)?;
        let manifest_before = std::fs::read(database.join("MANIFEST"))?;
        let source_before = std::fs::read(&source_wal)?;
        let seal_before = std::fs::read(source_wal.with_extension("seal"))?;

        let opened = KvEngine::open(&database, options);
        if let Ok(engine) = &opened {
            engine.close_storage()?;
        }
        let error = match opened {
            Ok(_) => anyhow::bail!("recreated a missing registered v7 successor"),
            Err(error) => error,
        };
        assert!(
            error
                .to_string()
                .contains("manifest-registered Active v7 WAL")
        );
        assert!(!successor_path.exists());
        assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
        assert_eq!(std::fs::read(&source_wal)?, source_before);
        assert_eq!(
            std::fs::read(source_wal.with_extension("seal"))?,
            seal_before
        );

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealed_recovery_rejects_legacy_source_replacements() -> anyhow::Result<()> {
        for flush_source in [false, true] {
            for version in [
                crate::pitr::WAL_V5_VERSION_LEGACY,
                crate::pitr::WAL_V5_VERSION,
            ] {
                let directory = tempdir()?;
                let (options, source_wal) = v7_sealed_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                if flush_source {
                    let engine = KvEngine::open(&database, options.clone())?;
                    assert!(!engine.inner.state.load().imm_memtables.is_empty());
                    while !engine.inner.state.load().imm_memtables.is_empty() {
                        engine.inner.force_flush_next_imm_memtable()?;
                    }
                    engine.close_storage()?;
                }
                let header =
                    crate::wal::v7::codec::WalV7Header::decode(&std::fs::read(&source_wal)?)?;
                let replacement = crate::pitr::encode_v5_file_header(crate::pitr::WalV5Header {
                    wal_format_version: version,
                    timeline_id: header.timeline_id,
                    archive_epoch_id: header.archive_epoch_id,
                    segment_id: header.segment_id,
                    predecessor: header.predecessor,
                })?;
                std::fs::write(&source_wal, replacement)?;
                let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                let opened = KvEngine::open(&database, options);
                if let Ok(engine) = &opened {
                    engine.close_storage()?;
                }
                assert!(
                    opened.is_err(),
                    "accepted legacy v{version} over a sealed v7 obligation with flush_source={flush_source}"
                );
                assert_eq!(std::fs::read(&source_wal)?, replacement);
                assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
            }
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_sealed_recovery_requires_retained_source_pair_after_flush() -> anyhow::Result<()> {
        use crate::manifest::ManifestRecord;

        for archived in [false, true] {
            for missing_wal in [false, true] {
                let directory = tempdir()?;
                let (options, source_wal) = v7_sealed_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let engine = KvEngine::open(&database, options.clone())?;
                while !engine.inner.state.load().imm_memtables.is_empty() {
                    engine.inner.force_flush_next_imm_memtable()?;
                }
                engine.close_storage()?;
                drop(engine);
                if archived {
                    let header =
                        crate::wal::v7::codec::WalV7Header::decode(&std::fs::read(&source_wal)?)?;
                    crate::manifest::Manifest::recover(database.join("MANIFEST"))?
                        .0
                        .add_record_when_init(ManifestRecord::Pitr(
                            crate::pitr::manifest::PitrManifestRecord::SegmentArchived {
                                segment_id: header.segment_id.0,
                            },
                        ))?;
                }
                let missing = if missing_wal {
                    source_wal.clone()
                } else {
                    source_wal.with_extension("seal")
                };
                std::fs::remove_file(&missing)?;
                let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                let opened = KvEngine::open(&database, options);
                if let Ok(engine) = &opened {
                    engine.close_storage()?;
                }
                assert!(
                    opened.is_err(),
                    "accepted a missing retained v7 source: archived={archived}, missing_wal={missing_wal}"
                );
                assert!(!missing.exists());
                assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
            }
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_reclaimable_unflushed_source_replays_before_cleanup() -> anyhow::Result<()> {
        use crate::{
            manifest::ManifestRecord,
            pitr::manifest::{ObligationState, PitrManifestRecord},
        };

        let directory = tempdir()?;
        let (options, source_wal) = v7_sealed_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let source_bytes = std::fs::read(&source_wal)?;
        let source_header = crate::wal::v7::codec::WalV7Header::decode(&source_bytes)?;
        let segment_id = source_header.segment_id.0;
        crate::manifest::Manifest::recover(database.join("MANIFEST"))?
            .0
            .add_records_when_init(&[
                ManifestRecord::Pitr(PitrManifestRecord::SegmentArchived { segment_id }),
                ManifestRecord::Pitr(PitrManifestRecord::SegmentReclaimable { segment_id }),
            ])?;

        let engine = KvEngine::open(&database, options.clone())?;
        assert_eq!(engine.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert_eq!(std::fs::read(&source_wal)?, source_bytes);
        assert_eq!(
            engine.pitr_manifest_state.lock().obligations[&segment_id].state,
            ObligationState::Reclaimable
        );
        let source = engine.inner.state.load().imm_memtables[0].clone();
        assert!(source.uses_v7_wal());
        assert!(source.uses_pitr_batch_wal());
        assert!(source.wal_v7_reservation_owner().is_none());
        drop(source);
        while !engine.inner.state.load().imm_memtables.is_empty() {
            engine.inner.force_flush_next_imm_memtable()?;
        }
        assert!(!source_wal.exists());
        assert!(!source_wal.with_extension("seal").exists());
        assert!(
            !engine
                .pitr_manifest_state
                .lock()
                .obligations
                .contains_key(&segment_id)
        );
        engine.close_storage()?;
        drop(engine);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        reopened.close_storage()?;

        Ok(())
    }

