    #[test]
    fn failpoint_v7_async_transaction_cancellation_during_capacity_retry_keeps_commit_owned()
    -> anyhow::Result<()> {
        v7_async_transaction_capacity_retry_is_owned_through_close(false)?;
        v7_async_transaction_capacity_retry_is_owned_through_close(true)
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_leader_async_write_finishes_capacity_retry_during_close() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let max_segment_bytes = 32 * 1024;
        let options =
            v7_recovery_test_database_with_segment_limit(directory.path(), max_segment_bytes)?;
        let database = directory.path().join("db");
        let engine = KvEngine::open_with_wal_io_mode(
            &database,
            options.clone(),
            crate::wal::WalIoMode::Leader,
        )?;
        suspend_pitr_maintenance_for_test(&engine);
        let initial_segment_id = engine
            .pitr_manifest_state
            .lock()
            .active_segment_id
            .expect("v7 Active segment is installed");

        engine.put(b"fill-one", b"value")?;
        engine.put(b"fill-two", b"value")?;
        let active = engine.inner.state.load().memtable.clone();
        let frontier = active.v7_frontier_cursor()?;
        let frame_len = crate::wal::v7::codec::WAL_V7_FRAME_LEN as u64;
        let physical_end = frontier.frame_offset + frame_len;
        assert!(physical_end <= max_segment_bytes);
        assert!(physical_end + 2 * frame_len > max_segment_bytes);

        // Hold the active memtable gate until close has started draining the
        // already-admitted Leader-mode write. Releasing it then forces the
        // write through the capacity retry while lifecycle admission is closed.
        let active_memtable_guard = engine.inner.active_memtable_lock.write();
        let writer_engine = Arc::clone(&engine);
        let writer = tokio::spawn(async move {
            writer_engine
                .write_batch_async(&[WriteBatchRecord::Put(
                    b"leader-retry".as_slice(),
                    b"durable".as_slice(),
                )])
                .await
        });
        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            while engine
                .inner
                .lifecycle
                .0
                .active_writes
                .load(std::sync::atomic::Ordering::Acquire)
                == 0
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("Leader-mode async writer must acquire lifecycle admission");

        let close_engine = Arc::clone(&engine);
        let close = tokio::spawn(async move { close_engine.close_async().await });
        let close_entered_write_drain =
            tokio::time::timeout(std::time::Duration::from_secs(5), async {
                while engine.inner.lifecycle.ensure_open().is_ok()
                    || !engine
                        .inner
                        .lifecycle
                        .0
                        .wait_for_writes_started
                        .load(std::sync::atomic::Ordering::Acquire)
                {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .is_ok();
        let admission_stayed_open = engine
            .inner
            .mvcc
            .as_ref()
            .expect("v7 storage has MVCC")
            .commit_admission_is_open();
        drop(active_memtable_guard);

        tokio::time::timeout(std::time::Duration::from_secs(5), writer)
            .await
            .expect("admitted Leader-mode async write must finish while close drains it")??;
        close.await??;
        assert!(
            close_entered_write_drain,
            "close must drain the admitted Leader-mode async write"
        );
        assert!(
            admission_stayed_open,
            "close must preserve MVCC admission until the Leader-mode write finishes"
        );
        assert_ne!(
            engine.pitr_manifest_state.lock().active_segment_id,
            Some(initial_segment_id),
            "capacity retry must rotate the full Active segment"
        );
        drop(engine);

        let reopened =
            KvEngine::open_with_wal_io_mode(&database, options, crate::wal::WalIoMode::Leader)?;
        for key in [b"fill-one".as_slice(), b"fill-two"] {
            assert_eq!(reopened.get(key)?, Some(Bytes::from_static(b"value")));
        }
        assert_eq!(
            reopened.get(b"leader-retry")?,
            Some(Bytes::from_static(b"durable"))
        );
        reopened.close_async().await?;
        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_storage_close_does_not_satisfy_pitr_close() -> anyhow::Result<()> {
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for async_storage_close in [false, true] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
                if async_storage_close {
                    engine.close_async().await?;
                } else {
                    engine.close()?;
                }
                let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                let wal_path = engine
                    .inner
                    .state
                    .load()
                    .memtable
                    .wal_path()
                    .unwrap()
                    .to_path_buf();
                let wal_before = std::fs::read(&wal_path)?;
                let error = engine.close_pitr().unwrap_err();
                assert!(error.to_string().contains("reopen"), "{error:#}");
                let error = engine.close_pitr_async().await.unwrap_err();
                assert!(error.to_string().contains("reopen"), "{error:#}");
                engine.close()?;
                engine.close_async().await?;
                assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
                assert_eq!(std::fs::read(&wal_path)?, wal_before);

                let reopened = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
                let point = match reopened.close_pitr()? {
                    crate::pitr::api::PitrCloseOutcome::ClosedDurably {
                        final_point: Some(point),
                    } => point,
                    outcome => {
                        anyhow::bail!("reopened PITR close did not publish a boundary: {outcome:?}")
                    }
                };
                assert_eq!(point.commit_ts, Some(7));
            }
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn pitr_repeated_close_preserves_the_cached_result() -> anyhow::Result<()> {
        for v7_mode in [
            None,
            Some(crate::wal::WalIoMode::Leader),
            Some(crate::wal::WalIoMode::Parallel),
        ] {
            for explicit_pitr_close in [false, true] {
                let directory = tempdir()?;
                let database = directory.path().join("db");
                let engine = if let Some(mode) = v7_mode {
                    let options = v7_recovery_test_database(directory.path())?;
                    KvEngine::open_with_wal_io_mode(&database, options, mode)?
                } else {
                    pitr_flush_test_engine(directory.path())
                };
                let initial_point = if explicit_pitr_close {
                    match engine.close_pitr()? {
                        crate::pitr::api::PitrCloseOutcome::ClosedDurably {
                            final_point: Some(point),
                        } => Some(point),
                        outcome => anyhow::bail!("initial PITR close failed: {outcome:?}"),
                    }
                } else {
                    engine.close()?;
                    None
                };
                let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                let state_before = engine.pitr_manifest_state.lock().clone();
                let segments_before = pitr_segment_wals(&database);
                engine.close()?;
                engine.close_async().await?;
                if v7_mode.is_some() && !explicit_pitr_close {
                    let error = engine.close_pitr().unwrap_err();
                    assert!(error.to_string().contains("reopen"), "{error:#}");
                    let error = engine.close_pitr_async().await.unwrap_err();
                    assert!(error.to_string().contains("reopen"), "{error:#}");
                } else {
                    let point = match engine.close_pitr()? {
                        crate::pitr::api::PitrCloseOutcome::ClosedDurably {
                            final_point: Some(point),
                        } => point,
                        outcome => anyhow::bail!("repeated PITR close lost its point: {outcome:?}"),
                    };
                    if let Some(initial_point) = initial_point {
                        assert_eq!(point, initial_point);
                    }
                    assert!(matches!(
                        engine.close_pitr_async().await?,
                        crate::pitr::api::PitrCloseOutcome::ClosedDurably {
                            final_point: Some(async_point)
                        } if async_point == point
                    ));
                }
                assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
                assert_eq!(*engine.pitr_manifest_state.lock(), state_before);
                assert_eq!(pitr_segment_wals(&database), segments_before);
            }
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[test]
    fn failpoint_v7_pitr_close_serializes_resume_through_shutdown() -> anyhow::Result<()> {
        use std::{sync::mpsc, time::Duration};

        let _scenario = crate::chaos::failpoint::FailScenario::setup();
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            let directory = tempdir()?;
            let options = v7_recovery_test_database(directory.path())?;
            let database = directory.path().join("db");
            let repository = directory.path().join("repository");
            let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
            let (entered_tx, entered_rx) = mpsc::channel();
            let (release_tx, release_rx) = mpsc::channel();
            let release_rx = parking_lot::Mutex::new(release_rx);
            let closing_engine = Arc::clone(&engine);
            fail::cfg_callback("pitr.after_close_recovery_point", move || {
                // Neither resume nor another boundary may enter between the
                // final recovery point and the transition to Closing.
                assert!(closing_engine.pitr_operation_lock.try_lock().is_none());
                assert!(closing_engine.pitr_barrier_lock.try_lock().is_none());
                entered_tx.send(()).unwrap();
                release_rx
                    .lock()
                    .recv_timeout(Duration::from_secs(5))
                    .unwrap();
            })
            .unwrap();
            let closing_engine = Arc::clone(&engine);
            let closing = std::thread::spawn(move || closing_engine.close_pitr());
            entered_rx.recv_timeout(Duration::from_secs(5))?;
            let resuming_engine = Arc::clone(&engine);
            let (resume_started_tx, resume_started_rx) = mpsc::channel();
            let resuming = std::thread::spawn(move || {
                resume_started_tx.send(()).unwrap();
                resuming_engine.resume_pitr(repository)
            });
            resume_started_rx.recv_timeout(Duration::from_secs(5))?;
            release_tx.send(())?;
            let close_result = closing.join().unwrap();
            let resume_result = resuming.join().unwrap();
            fail::remove("pitr.after_close_recovery_point");
            assert!(matches!(
                close_result?,
                crate::pitr::api::PitrCloseOutcome::ClosedDurably {
                    final_point: Some(_)
                }
            ));
            let error = resume_result.unwrap_err();
            assert!(
                error.to_string().contains("closing") || error.to_string().contains("closed"),
                "{error:#}"
            );
            assert!(
                !engine
                    .inner
                    .mvcc
                    .as_ref()
                    .unwrap()
                    .commit_admission_is_open()
            );
            assert!(engine.inner.lifecycle.is_closed());

            let reopened = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
            assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
            reopened.put(b"after-pitr-close", b"durable")?;
            reopened.close()?;
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_boundaries_reject_closed_handles_for_each_io_mode() -> anyhow::Result<()> {
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for empty_source in [false, true] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
                if empty_source {
                    engine.drain_flush()?;
                }
                engine.close_async().await?;
                let closed_memtable = engine.inner.state.load().memtable.clone();
                let closed_state = engine.pitr_manifest_state.lock().clone();

                for reopened in [false, true] {
                    // Close releases the exclusive v7 lock, so a stale handle must
                    // also remain harmless once another engine owns this directory.
                    let current = reopened
                        .then(|| KvEngine::open_with_wal_io_mode(&database, options.clone(), mode))
                        .transpose()?;
                    let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                    let wal_before = std::fs::read(closed_memtable.wal_path().unwrap())?;
                    let segments_before = pitr_segment_wals(&database);

                    let error = engine.create_recovery_point().unwrap_err();
                    assert!(error.to_string().contains("closed"), "{error:#}");
                    let error = engine.create_recovery_point_async().await.unwrap_err();
                    assert!(error.to_string().contains("closed"), "{error:#}");
                    let error = engine.force_flush().unwrap_err();
                    assert!(error.to_string().contains("closed"), "{error:#}");
                    let error = engine.drain_flush().unwrap_err();
                    assert!(error.to_string().contains("closed"), "{error:#}");

                    assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
                    assert_eq!(
                        std::fs::read(closed_memtable.wal_path().unwrap())?,
                        wal_before
                    );
                    assert_eq!(pitr_segment_wals(&database), segments_before);
                    assert_eq!(*engine.pitr_manifest_state.lock(), closed_state);
                    assert!(Arc::ptr_eq(
                        &engine.inner.state.load().memtable,
                        &closed_memtable
                    ));
                    assert!(
                        !engine
                            .inner
                            .mvcc
                            .as_ref()
                            .unwrap()
                            .commit_admission_is_open()
                    );
                    if let Some(current) = current {
                        assert_eq!(current.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
                        current.close_async().await?;
                    }
                }
            }
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[tokio::test(flavor = "current_thread")]
    async fn failpoint_v7_range_preparation_pins_sampled_memtable() -> anyhow::Result<()> {
        use std::{
            future::Future,
            sync::{
                atomic::{AtomicBool, Ordering},
                mpsc,
            },
            time::Duration,
        };

        let _scenario = crate::chaos::failpoint::FailScenario::setup();
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let engine = KvEngine::open_with_wal_io_mode(
            directory.path().join("db"),
            options,
            crate::wal::WalIoMode::Parallel,
        )?;
        let sampled = Arc::clone(&engine.inner);
        let observed = Arc::new(AtomicBool::new(false));
        let observed_callback = Arc::clone(&observed);
        fail::cfg_callback("pitr.v7_range_before_scratch_reservation", move || {
            // Rotation must not retire the sampled owner between its lookup
            // and scratch reservation. Once reserved, the token keeps its
            // resources alive independently of this short lease.
            assert!(sampled.active_memtable_lock.try_write().is_none());
            observed_callback.store(true, Ordering::Release);
        })
        .unwrap();
        let (held_tx, held_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let exclusive_inner = Arc::clone(&engine.inner);
        let exclusive = std::thread::spawn(move || {
            let _guard = exclusive_inner.active_memtable_lock.write();
            held_tx.send(()).unwrap();
            // Bound a regression that blocks the current-thread executor while
            // trying to acquire a synchronous read guard behind this writer.
            release_rx.recv_timeout(Duration::from_secs(5))
        });
        held_rx.recv_timeout(Duration::from_secs(5))?;
        let mut writing = Box::pin(engine.delete_range_async(b"v7-key", b"v7-key\xff"));
        let yielded = writing
            .as_mut()
            .poll(&mut std::task::Context::from_waker(std::task::Waker::noop()))
            .is_pending();
        let exclusive_still_held = engine
            .inner
            .active_memtable_lock
            .exclusive_pending_for_test();
        let released = release_tx.send(());
        let exclusive_result = exclusive.join().unwrap();
        let result = writing.await;
        fail::remove("pitr.v7_range_before_scratch_reservation");
        released?;
        exclusive_result?;
        result?;
        assert!(
            yielded && exclusive_still_held,
            "range preparation blocked the executor"
        );
        assert!(observed.load(Ordering::Acquire));
        assert_eq!(engine.get(b"v7-key")?, None);
        assert!(engine.inner.active_memtable_lock.try_write().is_some());
        engine.close_async().await?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_rotation_allows_queued_range_preparation() -> anyhow::Result<()> {
        use std::time::Duration;

        for forced_flush in [false, true] {
            let directory = tempdir()?;
            let options = v7_recovery_test_database(directory.path())?;
            let database = directory.path().join("db");
            let engine = KvEngine::open_with_wal_io_mode(
                &database,
                options.clone(),
                crate::wal::WalIoMode::Parallel,
            )?;
            let source = engine.inner.state.load().memtable.clone();
            let owner = source.wal_v7_reservation_owner().unwrap();
            let buffer_before = owner.snapshot().buffer_memory_bytes;
            let sequencer = engine.inner.mvcc.as_ref().unwrap();
            let preparation = sequencer.native_preparation_permit().await?;
            let writer_engine = Arc::clone(&engine);
            let writer = tokio::spawn(async move {
                writer_engine
                    .write_batch_async(&[WriteBatchRecord::DelRange(
                        b"v7-key".as_slice(),
                        b"v7-key\xff".as_slice(),
                    )])
                    .await
            });
            let queued = tokio::time::timeout(Duration::from_secs(5), async {
                while owner.snapshot().buffer_memory_bytes == buffer_before {
                    tokio::task::yield_now().await;
                }
            })
            .await;
            let boundary = if queued.is_err() {
                Err(anyhow::anyhow!(
                    "range preparation never reserved its buffer"
                ))
            } else if forced_flush {
                engine.force_flush()
            } else {
                engine.create_recovery_point().and_then(|outcome| {
                    anyhow::ensure!(
                        matches!(outcome, crate::pitr::api::RecoveryPointOutcome::Durable(_)),
                        "recovery point was not durable"
                    );
                    Ok(())
                })
            };
            // Let the queued task settle before propagating any boundary
            // failure, so an assertion cannot strand the native preparer.
            drop(preparation);
            let write_result = writer.await?;
            boundary?;
            write_result?;
            assert!(!Arc::ptr_eq(&source, &engine.inner.state.load().memtable));
            assert!(sequencer.commit_admission_is_open());
            assert_eq!(owner.snapshot().buffer_memory_bytes, buffer_before);
            assert_eq!(engine.get(b"v7-key")?, None);
            engine.put(b"after-rotation", b"writable")?;
            engine.close_async().await?;
            drop(engine);

            let reopened = KvEngine::open(&database, options)?;
            assert_eq!(reopened.get(b"v7-key")?, None);
            assert_eq!(
                reopened.get(b"after-rotation")?,
                Some(Bytes::from_static(b"writable"))
            );
            reopened.close_storage()?;
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[test]
    fn failpoint_v7_archive_reclaims_source_flushed_during_publication() -> anyhow::Result<()> {
        let _scenario = crate::chaos::failpoint::FailScenario::setup();
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for empty_source in [false, true] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
                if empty_source {
                    engine.drain_flush()?;
                }
                let source = engine.inner.state.load().memtable.clone();
                assert_eq!(source.is_empty(), empty_source);
                let source_id = LsmStorageInner::pitr_segment_of(&source).unwrap();
                let source_wal = source.wal_path().unwrap().to_path_buf();
                let owner = source.wal_v7_reservation_owner().unwrap();
                drop(source);

                let flushing = Arc::clone(&engine);
                let retained_wal = source_wal.clone();
                fail::cfg_callback("pitr.before_recovery_point_archive", move || {
                    while !flushing.inner.state.load().imm_memtables.is_empty() {
                        flushing.inner.force_flush_next_imm_memtable().unwrap();
                    }
                    assert_eq!(
                        flushing.pitr_manifest_state.lock().obligations[&source_id].state,
                        crate::pitr::manifest::ObligationState::Sealed
                    );
                    assert!(retained_wal.is_file());
                    assert!(retained_wal.with_extension("seal").is_file());
                })
                .unwrap();
                let boundary = engine.create_recovery_point();
                fail::remove("pitr.before_recovery_point_archive");
                assert!(matches!(
                    boundary?,
                    crate::pitr::api::RecoveryPointOutcome::Durable(_)
                ));
                assert!(
                    !engine
                        .pitr_manifest_state
                        .lock()
                        .obligations
                        .contains_key(&source_id)
                );
                assert!(!source_wal.exists());
                assert!(!source_wal.with_extension("seal").exists());
                let active_wal = engine
                    .inner
                    .state
                    .load()
                    .memtable
                    .wal_path()
                    .unwrap()
                    .to_path_buf();
                assert_eq!(
                    owner.snapshot().source_spool_bytes,
                    LsmStorageInner::filesystem_file_allocated_bytes(&active_wal)?
                );
                assert_eq!(owner.snapshot().seal_index_bytes, 0);
                drop(owner);
                engine.put(b"after-archive-cleanup", b"durable")?;
                engine.close_storage()?;
                drop(engine);

                let reopened = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
                assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
                assert_eq!(
                    reopened.get(b"after-archive-cleanup")?,
                    Some(Bytes::from_static(b"durable"))
                );
                reopened.close_storage()?;
            }
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[test]
    fn failpoint_v7_source_close_failure_does_not_register_successor() -> anyhow::Result<()> {
        let _scenario = crate::chaos::failpoint::FailScenario::setup();
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let repository = directory.path().join("repository");
        let engine = KvEngine::open_with_wal_io_mode(
            &database,
            options.clone(),
            crate::wal::WalIoMode::Parallel,
        )?;
        let source = engine.inner.state.load().memtable.clone();
        let successor_segment_id = engine.pitr_manifest_state.lock().next_segment_id;

        fail::cfg("parallel_wal.close_failure", "return").unwrap();
        let boundary = engine.create_recovery_point();
        let retry = engine.resume_pitr(&repository);
        fail::remove("parallel_wal.close_failure");
        assert!(
            format!("{:#}", boundary.unwrap_err()).contains("injected parallel WAL close failure")
        );
        assert!(
            format!("{:#}", retry.unwrap_err()).contains("injected parallel WAL close failure")
        );
        assert!(Arc::ptr_eq(&source, &engine.inner.state.load().memtable));
        assert!(
            !engine
                .inner
                .mvcc
                .as_ref()
                .unwrap()
                .commit_admission_is_open()
        );

        let (_, records) = crate::manifest::Manifest::recover(database.join("MANIFEST"))?;
        let successor_registrations = records
            .iter()
            .filter(|record| {
                matches!(record,
                    crate::manifest::ManifestRecord::NewPitrMemtable { segment_id, .. }
                        if *segment_id == successor_segment_id
                )
            })
            .count();
        assert_eq!(successor_registrations, 0);

        // Shutdown errors are cached by the runtime. Reopen must finish the
        // authorized successor without encountering duplicate registrations.
        assert!(engine.close_storage().is_err());
        drop(source);
        drop(engine);

        let reopened = KvEngine::open(&database, options.clone())?;
        assert!(matches!(
            reopened.resume_pitr(&repository)?,
            crate::pitr::api::PitrResumeOutcome::Resumed
        ));
        reopened.put(b"after-close-retry", b"durable")?;
        reopened.close_storage()?;
        drop(reopened);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert_eq!(
            reopened.get(b"after-close-retry")?,
            Some(Bytes::from_static(b"durable"))
        );
        reopened.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_forced_flush_rotates_before_reclaim_for_each_io_mode() -> anyhow::Result<()> {
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for operation in [
                "force_flush",
                "drain_flush",
                "force_flush_async",
                "drain_flush_async",
            ] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
                let source = engine.inner.state.load().memtable.clone();
                assert!(source.uses_v7_wal());
                let source_segment_id = LsmStorageInner::pitr_segment_of(&source).unwrap();
                let source_wal_path = source.wal_path().unwrap().to_path_buf();
                drop(source);

                engine.put(b"forced-flush-key", b"durable")?;
                match operation {
                    "force_flush" => engine.force_flush()?,
                    "drain_flush" => engine.drain_flush()?,
                    "force_flush_async" => engine.force_flush_async().await?,
                    "drain_flush_async" => engine.drain_flush_async().await?,
                    _ => unreachable!(),
                }

                let state = engine.pitr_manifest_state.lock().clone();
                assert_eq!(state.active_segment_id, Some(source_segment_id + 1));
                assert!(
                    !state.obligations.contains_key(&source_segment_id),
                    "{operation} left a reclaimed v7 source obligation behind"
                );
                assert!(!source_wal_path.exists());
                assert!(!source_wal_path.with_extension("seal").exists());
                let active = engine.inner.state.load();
                assert!(active.memtable.uses_v7_wal());
                assert!(active.imm_memtables.is_empty());
                assert_eq!(
                    LsmStorageInner::pitr_segment_of(&active.memtable),
                    state.active_segment_id
                );
                assert_eq!(engine.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
                assert_eq!(
                    engine.get(b"forced-flush-key")?,
                    Some(Bytes::from_static(b"durable"))
                );

                engine.close_storage()?;
                drop(engine);

                let reopened = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
                assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
                assert_eq!(
                    reopened.get(b"forced-flush-key")?,
                    Some(Bytes::from_static(b"durable"))
                );
                reopened.close_storage()?;
            }
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[tokio::test(flavor = "current_thread")]
    async fn failpoint_v7_forced_flush_retry_keeps_unresolved_archive_fenced() -> anyhow::Result<()>
    {
        let scenario = crate::chaos::failpoint::FailScenario::setup();
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for successor_write in [false, true] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let repository = directory.path().join("repository");
                let engine = KvEngine::open_with_wal_io_mode(&database, options.clone(), mode)?;
                suspend_pitr_maintenance_for_test(&engine);
                engine.put(b"before-archive-failure", b"durable")?;
                let source_wal = engine
                    .inner
                    .state
                    .load()
                    .memtable
                    .wal_path()
                    .unwrap()
                    .to_path_buf();

                if successor_write {
                    let writer = Arc::clone(&engine);
                    fail::cfg_callback("pitr.before_recovery_point_archive", move || {
                        writer
                            .put(b"during-archive-failure", b"durable")
                            .expect("commit in the successor while archival is in progress");
                    })
                    .unwrap();
                }
                crate::pitr::archiver::set_catalog_publication_test_mode(&repository, 1);
                let first_flush = engine.force_flush();
                fail::remove("pitr.before_recovery_point_archive");
                let error = first_flush.unwrap_err();
                assert!(
                    error
                        .to_string()
                        .contains("catalog directory fsync failure")
                );
                let state_after = engine.pitr_manifest_state.lock().clone();
                assert_eq!(
                    state_after.mode,
                    crate::pitr::manifest::PitrMode::PublicationUncertain
                );
                let active = engine.inner.state.load().memtable.clone();
                assert!(active.uses_v7_wal());
                assert_eq!(active.is_empty(), !successor_write);
                assert_eq!(engine.inner.state.load().imm_memtables.len(), 1);
                let manifest_after = std::fs::read(database.join("MANIFEST"))?;
                let source_after = std::fs::read(&source_wal)?;
                let successor_wal = active.wal_path().unwrap();
                let successor_after = std::fs::read(successor_wal)?;

                for operation in [
                    "force_flush",
                    "drain_flush",
                    "force_flush_async",
                    "drain_flush_async",
                ] {
                    let result = match operation {
                        "force_flush" => engine.force_flush(),
                        "drain_flush" => engine.drain_flush(),
                        "force_flush_async" => engine.force_flush_async().await,
                        "drain_flush_async" => engine.drain_flush_async().await,
                        _ => unreachable!(),
                    };
                    assert!(
                        result
                            .unwrap_err()
                            .to_string()
                            .contains("resume PITR first")
                    );
                    assert!(Arc::ptr_eq(&active, &engine.inner.state.load().memtable));
                    assert_eq!(engine.inner.state.load().imm_memtables.len(), 1);
                    assert_eq!(*engine.pitr_manifest_state.lock(), state_after);
                    assert_eq!(*engine.inner.pitr_state.lock(), state_after);
                    assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_after);
                    assert_eq!(std::fs::read(&source_wal)?, source_after);
                    assert_eq!(std::fs::read(successor_wal)?, successor_after);
                    assert!(source_wal.with_extension("seal").exists());
                    assert!(engine.put(b"must-stay-fenced", b"rejected").is_err());
                }

                assert!(matches!(
                    engine.resume_pitr(&repository)?,
                    crate::pitr::api::PitrResumeOutcome::Resumed
                ));
                engine.force_flush()?;
                assert!(!source_wal.exists());
                assert!(!source_wal.with_extension("seal").exists());
                engine.put(b"after-archive-resume", b"writable")?;
                engine.close_storage()?;
                drop(engine);

                let reopened = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
                assert_eq!(
                    reopened.get(b"before-archive-failure")?,
                    Some(Bytes::from_static(b"durable"))
                );
                assert_eq!(
                    reopened.get(b"after-archive-resume")?,
                    Some(Bytes::from_static(b"writable"))
                );
                if successor_write {
                    assert_eq!(
                        reopened.get(b"during-archive-failure")?,
                        Some(Bytes::from_static(b"durable"))
                    );
                }
                reopened.close_storage()?;
            }
        }
        scenario.teardown();

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    #[allow(deprecated)]
    async fn v7_pitr_backup_compatibility_apis_preserve_the_archived_chain() -> anyhow::Result<()> {
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            let directory = tempdir()?;
            let options = v7_recovery_test_database(directory.path())?;
            let database = directory.path().join("db");
            let repository_path = directory.path().join("repository");
            let engine = KvEngine::open_with_wal_io_mode(&database, options, mode)?;

            let sync_info = match engine.create_backup(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })? {
                crate::backup::CreateBackupOutcome::Committed(info) => info,
                outcome => anyhow::bail!("v7 PITR backup did not commit: {outcome:?}"),
            };
            assert_eq!(sync_info.backup_id, 2);

            let sync_compat_info = engine.create_backup_info(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })?;
            assert_eq!(sync_compat_info.backup_id, 3);

            let async_outcome = engine
                .create_backup_async_with_outcome(crate::backup::BackupOptions {
                    repository: repository_path.clone(),
                    use_hard_links: false,
                })
                .await?;
            let async_info = match async_outcome {
                crate::backup::BackupOutcome::Committed(info) => info,
                outcome => anyhow::bail!("async v7 PITR backup did not commit: {outcome:?}"),
            };
            assert_eq!(async_info.backup_id, 4);

            let async_info = engine
                .create_backup_async_info(crate::backup::BackupOptions {
                    repository: repository_path.clone(),
                    use_hard_links: false,
                })
                .await?;
            assert_eq!(async_info.backup_id, 5);

            let repository = crate::backup::BackupRepository::open(&repository_path)?;
            let page = repository.pitr_status_page(crate::pitr::api::PitrStatusOptions {
                cursor: None,
                page_size: crate::pitr::api::MAX_STATUS_PAGE_SIZE,
            })?;
            assert!(
                !page.items.is_empty(),
                "v7 backup capture must publish a PITR base bound to the archived source chain"
            );
            let verification = repository.verify_pitr(crate::pitr::api::VerifyPitrOptions {
                depth: crate::pitr::api::VerifyPitrDepth::Deep {
                    sampled_targets: NonZeroUsize::new(1).unwrap(),
                },
                selector: None,
                cursor: None,
                page_size: crate::pitr::api::MAX_STATUS_PAGE_SIZE,
            })?;
            assert!(verification.first_failure.is_none());
            assert!(!verification.verified_intervals.is_empty());

            drop(repository);
            engine.close_storage()?;
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    #[allow(deprecated)]
    async fn v7_pitr_backup_apis_handle_engine_moved_out_of_arc() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let repository_path = directory.path().join("repository");
        let engine =
            KvEngine::open_with_wal_io_mode(&database, options, crate::wal::WalIoMode::Parallel)?;
        let engine = std::sync::Arc::try_unwrap(engine)
            .unwrap_or_else(|_| panic!("test must hold the only KvEngine Arc reference"));

        assert!(
            engine
                .inner
                .weak_engine
                .get()
                .and_then(std::sync::Weak::upgrade)
                .is_none(),
            "moving the engine out of its Arc must make the weak owner unavailable"
        );

        let sync_info = engine.create_backup_info(crate::backup::BackupOptions {
            repository: repository_path.clone(),
            use_hard_links: false,
        })?;
        assert_eq!(sync_info.backup_id, 2);

        let async_info_error = engine
            .create_backup_async_info(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })
            .await
            .unwrap_err();
        assert!(
            async_info_error
                .to_string()
                .contains("retained KvEngine owner")
        );

        let async_outcome_error = engine
            .create_backup_async_with_outcome(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })
            .await
            .unwrap_err();
        assert!(
            async_outcome_error
                .to_string()
                .contains("retained KvEngine owner")
        );

        let task_error = engine
            .create_backup_task(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })?
            .await
            .unwrap_err();
        assert!(task_error.to_string().contains("retained KvEngine owner"));

        let async_task_error = engine
            .create_backup_async(crate::backup::BackupOptions {
                repository: repository_path,
                use_hard_links: false,
            })
            .await
            .unwrap_err();
        assert!(
            async_task_error
                .to_string()
                .contains("retained KvEngine owner")
        );

        engine.close_storage()?;
        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[tokio::test(flavor = "current_thread")]
    async fn failpoint_v7_pitr_backup_cancel_after_durable_boundary_reopens_admission()
    -> anyhow::Result<()> {
        let scenario = crate::chaos::failpoint::FailScenario::setup();
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            let directory = tempdir()?;
            let options = v7_recovery_test_database(directory.path())?;
            let repository_path = directory.path().join("repository");
            let engine =
                KvEngine::open_with_wal_io_mode(directory.path().join("db"), options, mode)?;
            suspend_pitr_maintenance_for_test(&engine);
            let backups_before = crate::backup::BackupRepository::open(&repository_path)?
                .list_info()?
                .len();
            let task = engine.create_backup_task(crate::backup::BackupOptions {
                repository: repository_path.clone(),
                use_hard_links: false,
            })?;
            let cancellation = task.cancellation_handle();
            // The current-thread runtime cannot dispatch the task until the
            // await below, so the cancellation point is installed first.
            fail::cfg_callback("pitr.before_backup_base_boundary", move || {
                cancellation.cancel();
            })
            .map_err(anyhow::Error::msg)?;
            let outcome = task.await?;
            fail::remove("pitr.before_backup_base_boundary");

            let admission_open = engine
                .inner
                .mvcc
                .as_ref()
                .unwrap()
                .commit_admission_is_open();
            let write_result = engine.put(b"after-cancel", b"writable");
            let backups_after = crate::backup::BackupRepository::open(&repository_path)?
                .list_info()?
                .len();
            engine.close_storage()?;

            assert!(matches!(
                outcome,
                crate::backup::BackupOutcome::CancelledBeforeCommit
            ));
            assert_eq!(backups_after, backups_before);
            assert!(
                admission_open,
                "clean cancellation left {mode:?} writes paused"
            );
            write_result?;
        }
        scenario.teardown();

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_checkpoint_capture_seals_and_flushes_the_fixed_cutoff() -> anyhow::Result<()> {
        for mode in [
            crate::wal::WalIoMode::Leader,
            crate::wal::WalIoMode::Parallel,
        ] {
            for asynchronous in [false, true] {
                let directory = tempdir()?;
                let options = v7_recovery_test_database(directory.path())?;
                let database = directory.path().join("db");
                let checkpoint_path = directory.path().join("checkpoint");
                let engine = KvEngine::open_with_wal_io_mode(&database, options, mode)?;
                engine.put(b"checkpoint-key", b"value")?;

                let active_before = engine.inner.state.load().memtable.clone();
                let segment_before = engine.pitr_manifest_state.lock().active_segment_id;
                if asynchronous {
                    engine.create_checkpoint_async(&checkpoint_path).await?;
                } else {
                    engine.create_checkpoint(&checkpoint_path)?;
                }

                let active_after = engine.inner.state.load().memtable.clone();
                assert!(!Arc::ptr_eq(&active_before, &active_after));
                assert!(active_after.uses_v7_wal());
                assert!(active_after.is_empty());
                assert_ne!(
                    engine.pitr_manifest_state.lock().active_segment_id,
                    segment_before
                );
                assert!(
                    engine
                        .inner
                        .mvcc
                        .as_ref()
                        .unwrap()
                        .commit_admission_is_open()
                );

                let checkpoint =
                    KvEngine::open(&checkpoint_path, LsmStorageOptions::default_for_test())?;
                assert_eq!(
                    checkpoint.get(b"checkpoint-key")?,
                    Some(Bytes::from_static(b"value"))
                );
                engine.put(b"after-checkpoint", b"newer")?;
                assert_eq!(checkpoint.get(b"after-checkpoint")?, None);
                checkpoint.close()?;
                engine.close_storage()?;
            }
        }

        Ok(())
    }

