    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_native_async_cancelled_caller_keeps_commit_owned_and_close_drains_it()
    -> anyhow::Result<()> {
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open_with_wal_io_mode(
            &database,
            options.clone(),
            crate::wal::WalIoMode::Parallel,
        )?;
        let active = engine.inner.state.load().memtable.clone();
        assert!(active.uses_v7_wal());
        assert!(active.uses_parallel_wal());
        let sequencer = engine.inner.mvcc.as_ref().unwrap();

        let pause = crate::lsm_storage::native_write::NativeWritePause::new(
            crate::lsm_storage::native_write::NativeWriteStage::Admitted,
        );
        *engine.inner.native_write_pause.lock() = Some(Arc::clone(&pause));
        let writer_engine = Arc::clone(&engine);
        let writer = tokio::spawn(async move {
            writer_engine
                .put_async(b"detached-v7-commit", b"durable")
                .await
        });
        pause.reached.notified().await;
        assert_eq!(engine.get(b"detached-v7-commit")?, None);
        writer.abort();
        assert!(writer.await.unwrap_err().is_cancelled());

        let close_engine = Arc::clone(&engine);
        let close = tokio::spawn(async move { close_engine.close_async().await });
        let close_entered_write_drain =
            tokio::time::timeout(std::time::Duration::from_secs(5), async {
                while engine.inner.lifecycle.ensure_open().is_ok()
                    || !engine
                        .inner
                        .lifecycle
                        .0
                        .wait_for_writes_started
                        .load(std::sync::atomic::Ordering::Acquire)
                {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .is_ok();
        let admission_stayed_open = sequencer.commit_admission_is_open();
        assert!(
            !close.is_finished(),
            "close must wait for the owned v7 commit"
        );
        pause.release.notify_one();
        close.await.unwrap()?;
        drop(engine);
        assert!(
            close_entered_write_drain,
            "close did not begin draining the admitted v7 commit"
        );
        assert!(
            admission_stayed_open,
            "close must preserve MVCC admission until the accepted v7 commit drains"
        );

        let reopened =
            KvEngine::open_with_wal_io_mode(&database, options, crate::wal::WalIoMode::Parallel)?;
        assert_eq!(
            reopened.get(b"detached-v7-commit")?,
            Some(Bytes::from_static(b"durable"))
        );
        reopened.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    async fn v7_native_async_range_commit_is_owned_through_close_and_recovery() -> anyhow::Result<()>
    {
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open_with_wal_io_mode(
            &database,
            options.clone(),
            crate::wal::WalIoMode::Parallel,
        )?;
        for key in [b"a".as_slice(), b"b", b"c", b"z"] {
            engine.put_async(key, b"value").await?;
        }

        let active = engine.inner.state.load().memtable.clone();
        let pause = crate::lsm_storage::native_write::NativeWritePause::new(
            crate::lsm_storage::native_write::NativeWriteStage::Admitted,
        );
        *engine.inner.native_write_pause.lock() = Some(Arc::clone(&pause));
        let writer_engine = Arc::clone(&engine);
        let writer =
            tokio::spawn(async move { writer_engine.delete_range_async(b"a", b"c").await });
        pause.reached.notified().await;
        assert_eq!(engine.get(b"a")?, Some(Bytes::from_static(b"value")));
        assert_eq!(engine.get(b"b")?, Some(Bytes::from_static(b"value")));
        writer.abort();
        assert!(writer.await.unwrap_err().is_cancelled());

        let sequencer = engine.inner.mvcc.as_ref().unwrap();
        let close_engine = Arc::clone(&engine);
        let close = tokio::spawn(async move { close_engine.close_async().await });
        let close_entered_write_drain =
            tokio::time::timeout(std::time::Duration::from_secs(5), async {
                while engine.inner.lifecycle.ensure_open().is_ok()
                    || !engine
                        .inner
                        .lifecycle
                        .0
                        .wait_for_writes_started
                        .load(std::sync::atomic::Ordering::Acquire)
                {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .is_ok();
        let admission_stayed_open = sequencer.commit_admission_is_open();
        let close_waits_for_commit = !close.is_finished();
        let wal_stays_open_during_drain = active.parallel_wal_is_closed() == Some(false);
        pause.release.notify_one();
        close.await.unwrap()?;
        drop(engine);
        assert!(
            close_entered_write_drain,
            "close did not begin draining the admitted range commit"
        );
        assert!(
            admission_stayed_open,
            "close must preserve MVCC admission until the accepted range commit drains"
        );
        assert!(
            close_waits_for_commit,
            "close must wait for the owned range commit"
        );
        assert!(
            wal_stays_open_during_drain,
            "the active parallel WAL must stay open while close drains the accepted commit"
        );

        let reopened =
            KvEngine::open_with_wal_io_mode(&database, options, crate::wal::WalIoMode::Parallel)?;
        assert_eq!(reopened.get(b"a")?, None);
        assert_eq!(reopened.get(b"b")?, None);
        assert_eq!(reopened.get(b"c")?, Some(Bytes::from_static(b"value")));
        assert_eq!(reopened.get(b"z")?, Some(Bytes::from_static(b"value")));
        reopened.close_async().await?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_async_large_batch_does_not_deadlock_on_buffer_budget() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let root = directory.path().to_path_buf();
        let (finished, completion) = std::sync::mpsc::channel();
        // A regression blocks synchronously inside buffer admission, so run the
        // operation off the test thread to bound failure independently of Tokio.
        let worker = std::thread::spawn(move || {
            let result = (|| -> anyhow::Result<()> {
                let fixture = pitr_flush_test_engine_with_segment_limit(&root, 128 << 20);
                let state = fixture.pitr_manifest_state.lock().clone();
                fixture.close_storage()?;
                drop(fixture);

                let options = install_v7_recovery_test_database(&root, state)?;
                let database = root.join("db");
                let engine = KvEngine::open(&database, options.clone())?;
                // One encoding fits the 64 MiB runtime buffer budget. Holding
                // both v4 preparation and v7 DATA buffers cannot fit.
                let value = vec![b'v'; 60 * 1024];
                let keys = (0..640)
                    .map(|index| format!("large-{index:04}").into_bytes())
                    .collect::<Vec<_>>();
                let batch = keys
                    .iter()
                    .map(|key| WriteBatchRecord::Put(key.as_slice(), value.as_slice()))
                    .collect::<Vec<_>>();
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()?;
                runtime.block_on(engine.write_batch_async(&batch))?;
                assert_eq!(engine.get(&keys[0])?.as_deref(), Some(value.as_slice()));
                assert_eq!(engine.get(&keys[639])?.as_deref(), Some(value.as_slice()));
                engine.close()?;
                drop(engine);

                let reopened = KvEngine::open(&database, options)?;
                assert_eq!(reopened.get(&keys[0])?.as_deref(), Some(value.as_slice()));
                assert_eq!(reopened.get(&keys[639])?.as_deref(), Some(value.as_slice()));
                reopened.close()?;

                Ok(())
            })();
            let _ = finished.send(result);
        });
        let result = completion
            .recv_timeout(std::time::Duration::from_secs(20))
            .map_err(|error| anyhow::anyhow!("v7 async batch did not complete: {error}"))?;
        worker.join().unwrap();

        result
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_disable_preserves_active_manifest_and_wal() -> anyhow::Result<()> {
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open(&database, options.clone())?;
        let active = engine.inner.state.load().memtable.clone();
        assert!(active.uses_v7_wal());
        assert!(!active.is_empty());
        let wal_path = active.wal_path().unwrap();
        let wal_before = std::fs::read(wal_path)?;
        let manifest_before = std::fs::read(database.join("MANIFEST"))?;
        let pitr_before = engine.pitr_manifest_state.lock().clone();

        let error = engine.disable_pitr().unwrap_err();
        assert!(error.to_string().contains("post-PITR WAL rotation"));
        assert_eq!(*engine.pitr_manifest_state.lock(), pitr_before);
        assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
        assert_eq!(std::fs::read(wal_path)?, wal_before);
        let error = engine.disable_pitr_allow_gap().unwrap_err();
        assert!(error.to_string().contains("post-PITR WAL rotation"));
        assert_eq!(*engine.pitr_manifest_state.lock(), pitr_before);
        assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
        assert_eq!(std::fs::read(wal_path)?, wal_before);
        let active_guard = engine.inner.active_memtable_lock.write();
        let successor = crate::mem_table::MemTable::create(active.id() + 1, false);
        assert!(
            engine
                .inner
                .force_freeze_with_new_memtable_locked(successor, &active_guard)
                .is_err()
        );
        drop(active_guard);
        assert!(Arc::ptr_eq(&engine.inner.state.load().memtable, &active));
        assert!(engine.inner.state.load().imm_memtables.is_empty());
        assert_eq!(std::fs::read(wal_path)?, wal_before);
        engine.put(b"after-failed-freeze", b"durable")?;
        assert_eq!(
            engine.get(b"after-failed-freeze")?,
            Some(Bytes::from_static(b"durable"))
        );
        engine.close()?;
        drop(engine);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert_eq!(
            reopened.get(b"after-failed-freeze")?,
            Some(Bytes::from_static(b"durable"))
        );
        reopened.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_wal_without_manifest_authority_cannot_be_hidden_by_initialization() -> anyhow::Result<()>
    {
        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let wal_path = pitr_segment_wals(&database).pop().unwrap().1;
        let before = std::fs::read(&wal_path)?;
        assert_eq!(
            u16::from_be_bytes(before[4..6].try_into()?),
            crate::wal::format::WAL_FORMAT_VERSION_V7
        );
        std::fs::remove_file(database.join("MANIFEST"))?;
        for snapshot in ["ENGINE_MANIFEST", "ENGINE_MANIFEST.tmp"] {
            let path = database.join(snapshot);
            if path.try_exists()? {
                std::fs::remove_file(path)?;
            }
        }

        for enable_wal in [false, true] {
            let mut options = options.clone();
            options.enable_wal = enable_wal;
            assert!(KvEngine::open(&database, options).is_err());
            assert!(!database.join("MANIFEST").exists());
            assert_eq!(std::fs::read(&wal_path)?, before);
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_manifest_boundary_rejects_legacy_active_replacement() -> anyhow::Result<()> {
        for version in [
            crate::pitr::WAL_V5_VERSION_LEGACY,
            crate::pitr::WAL_V5_VERSION,
        ] {
            for enable_wal in [true, false] {
                let directory = tempdir()?;
                let mut options = v7_recovery_test_database(directory.path())?;
                options.enable_wal = enable_wal;
                let database = directory.path().join("db");
                let wal_path = pitr_segment_wals(&database).pop().unwrap().1;
                let header =
                    crate::wal::v7::codec::WalV7Header::decode(&std::fs::read(&wal_path)?)?;
                // A stale legacy image can match the segment identity while
                // omitting every commit protected by the v7 manifest floor.
                let replacement = crate::pitr::encode_v5_file_header(crate::pitr::WalV5Header {
                    wal_format_version: version,
                    timeline_id: header.timeline_id,
                    archive_epoch_id: header.archive_epoch_id,
                    segment_id: header.segment_id,
                    predecessor: header.predecessor,
                })?;
                std::fs::write(&wal_path, replacement)?;
                let manifest_before = std::fs::read(database.join("MANIFEST"))?;
                let opened = KvEngine::open(&database, options);
                if let Ok(engine) = &opened {
                    engine.close_storage()?;
                }
                assert!(
                    opened.is_err(),
                    "accepted legacy v{version} over a v7 manifest boundary with enable_wal={enable_wal}"
                );
                assert_eq!(std::fs::read(&wal_path)?, replacement);
                assert_eq!(std::fs::read(database.join("MANIFEST"))?, manifest_before);
            }
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_recovery_uses_snapshot_authority_without_manifest() -> anyhow::Result<()> {
        for pending_snapshot in [false, true] {
            let directory = tempdir()?;
            let mut options = v7_recovery_test_database(directory.path())?;
            options.manifest_snapshot_threshold_bytes = 1;
            let database = directory.path().join("db");
            let engine = KvEngine::open(&database, options.clone())?;
            let boundary = engine.pitr_manifest_state.lock().active_boundary;
            engine
                .inner
                .maybe_snapshot_manifest(&engine.inner.state_lock.lock())?;
            assert!(database.join("ENGINE_MANIFEST").exists());
            engine.close_storage()?;
            drop(engine);

            if pending_snapshot {
                std::fs::rename(
                    database.join("ENGINE_MANIFEST"),
                    database.join("ENGINE_MANIFEST.tmp"),
                )?;
            }
            std::fs::remove_file(database.join("MANIFEST"))?;
            let reopened = KvEngine::open(&database, options)?;
            assert!(reopened.inner.state.load().memtable.uses_v7_wal());
            assert_eq!(
                reopened.pitr_manifest_state.lock().active_boundary,
                boundary
            );
            assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
            assert!(database.join("MANIFEST").exists());
            assert!(database.join("ENGINE_MANIFEST").exists());
            assert!(!database.join("ENGINE_MANIFEST.tmp").exists());
            reopened.close_storage()?;
        }

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_recovery_keeps_flushed_legacy_sources_until_reconciliation() -> anyhow::Result<()> {
        use crate::pitr::manifest::ObligationState;

        let directory = tempdir()?;
        let database = directory.path().join("db");
        let engine = pitr_flush_test_engine(directory.path());
        engine.put(b"legacy-key", b"legacy-value")?;
        let legacy_segment = engine.pitr_manifest_state.lock().active_segment_id.unwrap();
        assert!(matches!(
            engine.create_recovery_point()?,
            crate::pitr::api::RecoveryPointOutcome::Durable(_)
        ));
        engine.close_storage()?;
        drop(engine);

        // Model the valid archived-but-not-yet-reclaimable boundary. Flush its
        // memtable through the storage path while keeping the archive source.
        let storage = LsmStorageInner::open_with_wal_io_mode(
            &database,
            LsmStorageOptions {
                enable_wal: true,
                manifest_snapshot_threshold_bytes: 1,
                ..LsmStorageOptions::default_for_test()
            },
            crate::wal::WalIoMode::Leader,
        )?;
        let mut state = storage.pitr_state.lock().clone();
        state.obligations.get_mut(&legacy_segment).unwrap().state = ObligationState::Archived;
        state.validate_for_status()?;
        *storage.pitr_state.lock() = state.clone();
        while !storage.state.load().imm_memtables.is_empty() {
            storage.force_flush_next_imm_memtable()?;
        }
        assert!(database.join("ENGINE_MANIFEST").exists());
        let legacy_path = database.join(format!("pitr-{legacy_segment:020}.wal"));
        let retained = std::fs::read(&legacy_path)?;
        assert!(retained.len() > crate::pitr::WAL_V5_HEADER_LEN);
        drop(storage);

        let mut options = install_v7_recovery_test_database(directory.path(), state)?;
        options.pitr_repository = None;
        let reopened = KvEngine::open(&database, options.clone())?;
        assert!(reopened.inner.state.load().memtable.uses_v7_wal());
        assert!(reopened.inner.state.load().imm_memtables.is_empty());
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert_eq!(
            reopened.get(b"legacy-key")?,
            Some(Bytes::from_static(b"legacy-value"))
        );
        assert_eq!(std::fs::read(&legacy_path)?, retained);
        assert_eq!(
            reopened.pitr_manifest_state.lock().obligations[&legacy_segment].state,
            ObligationState::Archived
        );
        reopened.close_storage()?;
        drop(reopened);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        assert_eq!(
            reopened.get(b"legacy-key")?,
            Some(Bytes::from_static(b"legacy-value"))
        );
        reopened.close_storage()?;

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_flush_releases_recovered_source_without_segment_manager() -> anyhow::Result<()> {
        for with_engine in [true, false] {
            let directory = tempdir()?;
            let database = directory.path().join("db");
            let engine = pitr_flush_test_engine(directory.path());
            engine.put(b"legacy-key", b"legacy-value")?;
            let legacy_segment = engine.pitr_manifest_state.lock().active_segment_id.unwrap();
            assert!(matches!(
                engine.create_recovery_point()?,
                crate::pitr::api::RecoveryPointOutcome::Durable(_)
            ));
            let state = engine.pitr_manifest_state.lock().clone();
            assert_eq!(
                state.obligations[&legacy_segment].state,
                crate::pitr::manifest::ObligationState::Reclaimable
            );
            engine.close_storage()?;
            drop(engine);

            let mut options = install_v7_recovery_test_database(directory.path(), state)?;
            options.pitr_repository = None;
            let reopened = with_engine
                .then(|| KvEngine::open(&database, options.clone()))
                .transpose()?;
            let storage = match &reopened {
                Some(engine) => {
                    assert!(engine.pitr_segments.lock().is_none());
                    Arc::clone(&engine.inner)
                }
                None => Arc::new(LsmStorageInner::open_with_wal_io_mode(
                    &database,
                    options,
                    crate::wal::WalIoMode::Leader,
                )?),
            };
            let active = storage.state.load().memtable.clone();
            let owner = active.wal_v7_reservation_owner().unwrap();
            let active_allocated =
                LsmStorageInner::filesystem_file_allocated_bytes(active.wal_path().unwrap())?;
            assert!(owner.snapshot().source_spool_bytes > active_allocated);
            assert!(!storage.state.load().imm_memtables.is_empty());

            storage.force_flush_next_imm_memtable()?;
            let legacy_path = database.join(format!("pitr-{legacy_segment:020}.wal"));
            assert!(!legacy_path.exists());
            assert!(!legacy_path.with_extension("seal").exists());
            assert!(
                !storage
                    .pitr_state
                    .lock()
                    .obligations
                    .contains_key(&legacy_segment)
            );
            assert_eq!(owner.snapshot().source_spool_bytes, active_allocated);
            assert_eq!(
                storage.get(b"legacy-key")?,
                Some(Bytes::from_static(b"legacy-value"))
            );
            if let Some(engine) = reopened {
                assert!(engine.pitr_segments.lock().is_none());
                assert!(
                    !engine
                        .pitr_manifest_state
                        .lock()
                        .obligations
                        .contains_key(&legacy_segment)
                );
                engine.close_storage()?;
            }
        }

        Ok(())
    }

    #[cfg(all(target_os = "linux", feature = "chaos-testing"))]
    #[test]
    fn failpoint_v7_reconciliation_retry_releases_durably_cleaned_source_charge()
    -> anyhow::Result<()> {
        use crate::{
            chaos::failpoint::FailScenario,
            pitr::manifest::{ObligationState, PitrManifestRecord},
        };

        let scenario = FailScenario::setup();
        let directory = tempdir()?;
        let database = directory.path().join("db");
        let engine = pitr_flush_test_engine(directory.path());
        engine.put(b"legacy-key", b"legacy-value")?;
        let legacy_segment = engine.pitr_manifest_state.lock().active_segment_id.unwrap();
        assert!(matches!(
            engine.create_recovery_point()?,
            crate::pitr::api::RecoveryPointOutcome::Durable(_)
        ));
        engine.close_storage()?;
        drop(engine);

        // Flush the legacy memtable while retaining its archived source, then
        // durably mark it reclaimable without running source cleanup yet.
        let storage = LsmStorageInner::open_with_wal_io_mode(
            &database,
            LsmStorageOptions {
                enable_wal: true,
                manifest_snapshot_threshold_bytes: 1,
                ..LsmStorageOptions::default_for_test()
            },
            crate::wal::WalIoMode::Leader,
        )?;
        let mut state = storage.pitr_state.lock().clone();
        state.obligations.get_mut(&legacy_segment).unwrap().state = ObligationState::Archived;
        state.validate_for_status()?;
        *storage.pitr_state.lock() = state.clone();
        while !storage.state.load().imm_memtables.is_empty() {
            storage.force_flush_next_imm_memtable()?;
        }
        drop(storage);
        let reclaimable = PitrManifestRecord::SegmentReclaimable {
            segment_id: legacy_segment,
        };
        crate::manifest::Manifest::recover(database.join("MANIFEST"))?
            .0
            .add_record_when_init(crate::manifest::ManifestRecord::Pitr(reclaimable.clone()))?;
        state = crate::pitr::manifest::replay_pitr_records([
            PitrManifestRecord::Snapshot(Box::new(state)),
            reclaimable,
        ])?;

        let mut options = install_v7_recovery_test_database(directory.path(), state)?;
        options.pitr_repository = None;
        let reopened = KvEngine::open(&database, options)?;
        let state = reopened.pitr_manifest_state.lock().clone();
        reopened.install_pitr_lifecycle(
            state.clone(),
            &crate::pitr::api::PitrRuntimeOptions::default(),
        )?;
        let active = reopened.inner.state.load().memtable.clone();
        let owner = active.wal_v7_reservation_owner().unwrap();
        let active_allocated =
            LsmStorageInner::filesystem_file_allocated_bytes(active.wal_path().unwrap())?;
        let before = owner.snapshot();
        assert!(before.source_spool_bytes > active_allocated);

        fail::cfg("manifest.after_append_before_sync", "return").unwrap();
        let result = reopened.reconcile_durable_archive_obligations(state);
        fail::remove("manifest.after_append_before_sync");
        assert!(matches!(
            result
                .unwrap_err()
                .downcast_ref::<super::PitrManifestPublicationError>(),
            Some(super::PitrManifestPublicationError::PublishedButNotDurable(
                _
            ))
        ));
        let legacy_path = database.join(format!("pitr-{legacy_segment:020}.wal"));
        assert!(!legacy_path.exists());
        assert!(!legacy_path.with_extension("seal").exists());
        let state = reopened.pitr_manifest_state.lock().clone();
        assert!(state.obligations.is_empty());
        assert_eq!(
            owner.snapshot(),
            before,
            "failed publication must retain source charges"
        );
        assert!(
            reopened
                .pitr_segments
                .lock()
                .as_ref()
                .unwrap()
                .has_pending_obligation_reconciliation()
        );

        reopened.reconcile_durable_archive_obligations(state)?;
        assert_eq!(owner.snapshot().source_spool_bytes, active_allocated);
        {
            let segments = reopened.pitr_segments.lock();
            let segments = segments.as_ref().unwrap();
            assert!(segments.segment(legacy_segment).is_none());
            assert!(!segments.has_pending_obligation_reconciliation());
        }
        reopened.close_storage()?;
        scenario.teardown();

        Ok(())
    }

    #[test]
    fn v7_recovery_reconstructs_source_spool_from_allocated_wal_and_seal_files()
    -> anyhow::Result<()> {
        use crate::pitr::manifest::{ObligationState, PersistedPitrConfig};

        const ACTIVE_SOURCE_LEN: usize = 16 * 1024;
        const LEGACY_WAL_LEN: usize = 32 * 1024;
        const LEGACY_SEAL_LEN: usize = 12 * 1024;
        const MAX_SEGMENT_BYTES: u64 = 32 * 1024;

        for archived_state in [ObligationState::Archived, ObligationState::Reclaimable] {
            let directory = tempdir()?;
            let database_path = directory.path();
            let active_path = database_path.join("pitr-00000000000000000002.wal");
            let legacy_wal_path = database_path.join("pitr-00000000000000000001.wal");
            let legacy_seal_path = database_path.join("pitr-00000000000000000001.seal");
            let orphan_wal_path = database_path.join("pitr-00000000000000000003.wal");
            let staged_wal_path = database_path.join(".pitr-00000000000000000004.wal.tmp-123-1");
            let active_recovery_prefix =
                crate::wal::v7::install::recovery_temp_prefix(active_path.file_name().unwrap());
            let active_recovery_path = database_path.join(format!("{active_recovery_prefix}123-2"));
            let orphan_recovery_prefix = crate::wal::v7::install::recovery_temp_prefix(
                std::ffi::OsStr::new("pitr-00000000000000000006.wal"),
            );
            let orphan_recovery_path = database_path.join(format!("{orphan_recovery_prefix}123-3"));
            write_random_file(&active_path, ACTIVE_SOURCE_LEN, 1)?;
            write_random_file(&legacy_wal_path, LEGACY_WAL_LEN, 2)?;
            write_random_file(&legacy_seal_path, LEGACY_SEAL_LEN, 3)?;
            write_random_file(&orphan_wal_path, 4096, 4)?;
            write_random_file(&staged_wal_path, 4096, 5)?;
            write_random_file(&active_recovery_path, 8192, 6)?;
            write_random_file(&orphan_recovery_path, 4096, 7)?;

            let active_allocated = LsmStorageInner::filesystem_file_allocated_bytes(&active_path)?;
            let legacy_allocated =
                LsmStorageInner::filesystem_file_allocated_bytes(&legacy_wal_path)?
                    .checked_add(LsmStorageInner::filesystem_file_allocated_bytes(
                        &legacy_seal_path,
                    )?)
                    .unwrap();
            assert!(
                legacy_allocated > LEGACY_WAL_LEN as u64 + 4096,
                "the multi-page seal allocation must exceed the old one-frame estimate"
            );
            let other_source_allocated =
                LsmStorageInner::pitr_other_source_allocated_bytes(database_path, 2)?;
            let orphan_allocated =
                LsmStorageInner::filesystem_file_allocated_bytes(&orphan_wal_path)?;
            let staged_allocated =
                LsmStorageInner::filesystem_file_allocated_bytes(&staged_wal_path)?;
            let orphan_recovery_allocated =
                LsmStorageInner::filesystem_file_allocated_bytes(&orphan_recovery_path)?;
            let expected_other_source_allocated = legacy_allocated
                .checked_add(orphan_allocated)
                .and_then(|bytes| bytes.checked_add(staged_allocated))
                .and_then(|bytes| bytes.checked_add(orphan_recovery_allocated))
                .unwrap();
            assert_eq!(other_source_allocated, expected_other_source_allocated);

            let required_source_spool = active_allocated
                .checked_add(other_source_allocated)
                .and_then(|bytes| bytes.checked_add(MAX_SEGMENT_BYTES))
                .unwrap();
            let config = PersistedPitrConfig {
                archive_interval_ms: 1000,
                max_segment_bytes: MAX_SEGMENT_BYTES,
                max_unarchived_bytes: 32 * 1024,
                max_source_spool_bytes: required_source_spool,
            };
            let mut state = enabled_pitr_state_with_sealed_segment(config.clone(), 32 * 1024);
            state.obligations.get_mut(&1).unwrap().state = archived_state;
            state.validate_for_status()?;
            let (retained, workspace, _) = LsmStorageInner::reserve_v7_active_recovery_workspace(
                &state,
                database_path,
                2,
                ACTIVE_SOURCE_LEN as u64,
                active_allocated,
            )?;
            assert_eq!(retained.snapshot().logical_wal_bytes, 8 * 1024);
            assert_eq!(
                retained.snapshot().source_spool_bytes,
                active_allocated + other_source_allocated
            );
            assert_eq!(retained.snapshot().recovery_workspace_bytes, 32 * 1024);
            drop(workspace);

            // Archived/reclaimable sources remain charged while their files are
            // still allocated. The multi-page seal is included in that charge.
            state.config.as_mut().unwrap().max_source_spool_bytes =
                required_source_spool.saturating_sub(1);
            assert!(
                LsmStorageInner::reserve_v7_active_recovery_workspace(
                    &state,
                    database_path,
                    2,
                    ACTIVE_SOURCE_LEN as u64,
                    active_allocated,
                )
                .is_err()
            );

            for malformed_name in [
                ".pitr-00000000000000000005.seal.tmp-123-4".to_owned(),
                format!("{active_recovery_prefix}123-4"),
            ] {
                let malformed_staging_dir = database_path.join(malformed_name);
                std::fs::create_dir(&malformed_staging_dir)?;
                write_random_file(&malformed_staging_dir.join("payload"), 4096, 8)?;
                assert!(
                    LsmStorageInner::pitr_other_source_allocated_bytes(database_path, 2).is_err(),
                    "a recognized staging path must be a regular file"
                );
                std::fs::remove_dir_all(malformed_staging_dir)?;
            }
        }

        let directory = tempdir()?;
        let unarchived = enabled_pitr_state_with_sealed_segment(
            PersistedPitrConfig {
                archive_interval_ms: 1000,
                max_segment_bytes: MAX_SEGMENT_BYTES,
                max_unarchived_bytes: 32 * 1024,
                max_source_spool_bytes: 256 * 1024,
            },
            32 * 1024,
        );
        assert!(
            LsmStorageInner::reserve_v7_active_recovery_workspace(
                &unarchived,
                directory.path(),
                2,
                ACTIVE_SOURCE_LEN as u64,
                0,
            )
            .is_err()
        );

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[tokio::test]
    async fn v7_async_close_preserves_io_error_after_admission_failure() -> anyhow::Result<()> {
        use super::async_close::{AsyncCloseError, AsyncCloseErrorKind};

        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open(&database, options)?;
        let sequencer = engine.inner.mvcc.as_ref().unwrap();
        sequencer.poison_commit_ts(sequencer.latest_commit_ts() + 1);
        std::fs::rename(&database, directory.path().join("moved-db"))?;

        let error = engine.close_async().await.unwrap_err();
        let error = error.downcast_ref::<AsyncCloseError>().unwrap();
        assert_eq!(
            error.kind(),
            AsyncCloseErrorKind::Io(std::io::ErrorKind::NotFound)
        );
        assert_eq!(
            error
                .source_error()
                .downcast_ref::<std::io::Error>()
                .unwrap()
                .kind(),
            std::io::ErrorKind::NotFound
        );
        let repeated = engine.close_async().await.unwrap_err();
        assert_eq!(
            repeated.downcast_ref::<AsyncCloseError>().unwrap().kind(),
            error.kind()
        );

        Ok(())
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn v7_close_waiters_observe_released_open_lock() -> anyhow::Result<()> {
        use std::{sync::mpsc, time::Duration};

        let directory = tempdir()?;
        let options = v7_recovery_test_database(directory.path())?;
        let database = directory.path().join("db");
        let engine = KvEngine::open(&database, options.clone())?;
        // Delay ownership release to expose the completion ordering to a
        // concurrent close waiter, even if the first closer would run quickly.
        let ownership = engine.inner.wal_v7_open_lock.lock();
        assert!(ownership.is_some());
        let first_engine = Arc::clone(&engine);
        let first = std::thread::spawn(move || first_engine.close());
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while engine.inner.lifecycle.ensure_open().is_ok() {
            assert!(std::time::Instant::now() < deadline, "close did not start");
            std::thread::sleep(Duration::from_millis(1));
        }
        let (completed_tx, completed_rx) = mpsc::channel();
        let second_engine = Arc::clone(&engine);
        let second = std::thread::spawn(move || {
            let result = second_engine.close();
            completed_tx.send(result.is_ok()).unwrap();

            result
        });
        let early_completion = completed_rx.recv_timeout(Duration::from_millis(500));
        let closed_before_release = engine.inner.lifecycle.is_closed();
        drop(ownership);
        first.join().unwrap()?;
        second.join().unwrap()?;
        assert!(
            !closed_before_release,
            "close completed before releasing ownership"
        );
        assert!(matches!(
            early_completion,
            Err(mpsc::RecvTimeoutError::Timeout)
        ));
        assert!(
            !engine
                .inner
                .mvcc
                .as_ref()
                .unwrap()
                .commit_admission_is_open()
        );
        assert!(engine.put(b"after-close", b"rejected").is_err());
        assert!(engine.resume_pitr(database.join("repository")).is_err());
        assert!(
            !engine
                .inner
                .mvcc
                .as_ref()
                .unwrap()
                .commit_admission_is_open()
        );
        drop(engine);

        let reopened = KvEngine::open(&database, options)?;
        assert_eq!(reopened.get(b"v7-key")?, Some(Bytes::from_static(b"v")));
        reopened.close()?;

        Ok(())
    }

    /// `close_async` on an enabled PITR lifecycle has to run the close off the
    /// executor.
    ///
    /// The close joins the PITR worker threads and then waits for lifecycle
    /// quiescence, which waits for an admitted operation to drop its guard. On a
    /// `current_thread` runtime the only thread that can poll that operation - and
    /// so release the guard - is the one inside `close_async`, so running the close
    /// inline waits for a guard only itself can free.
    ///
    /// What this test actually detects on a regression is that the runtime stopped
    /// polling: with the close inline, the guard task is never polled, so its
    /// `admit_scan` is never reached and the ticker never runs. The deadlock proper
    /// needs the guard to be admitted and *parked* before the close starts, released
    /// by a third thread later - an arrangement that would make this test hang
    /// rather than fail, which is why it is not used here. The assertion on the
    /// ticker is what rules out passing vacuously.
    ///
    /// The close runs on its own thread and is joined with a timeout, so a
    /// regression fails here instead of hanging the test binary until nextest kills
    /// it.
    #[cfg(target_os = "linux")]
    #[test]
    fn close_async_with_pitr_enabled_does_not_block_the_runtime_thread() {
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let engine = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        engine
            .enable_pitr(crate::pitr::api::PitrOptions {
                repository: repository.clone(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval: std::time::Duration::from_secs(3600),
                    max_segment_bytes: 1 << 20,
                    max_unarchived_bytes: 1 << 20,
                    max_source_spool_bytes: 8 << 20,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        for index in 0..64_u32 {
            engine
                .put(format!("key-{index:03}").as_bytes(), b"value")
                .unwrap();
        }

        let runtime = std::sync::Arc::new(
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap(),
        );
        // Held across the whole close: the guard `wait_for_quiescence` is waiting
        // for, dropped only once this task is polled after its sleep.
        let guard_engine = std::sync::Arc::clone(&engine);
        let guard = runtime.spawn(async move {
            let _guard = guard_engine
                .inner
                .lifecycle
                .admit_scan()
                .expect("admit a scan the close has to wait for");
            tokio::time::sleep(std::time::Duration::from_millis(250)).await;
        });
        let ticks = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let ticker_ticks = std::sync::Arc::clone(&ticks);
        let ticker = runtime.spawn(async move {
            loop {
                tokio::time::sleep(std::time::Duration::from_millis(1)).await;
                ticker_ticks.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            }
        });

        let close_runtime = std::sync::Arc::clone(&runtime);
        let (sender, receiver) = std::sync::mpsc::channel();
        let closing_engine = std::sync::Arc::clone(&engine);
        std::thread::spawn(move || {
            let outcome = close_runtime.block_on(closing_engine.close_async());
            let _ = sender.send(outcome.is_ok());
        });
        let finished = receiver
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("close_async must not block the runtime thread the close waits on");
        assert!(finished, "close_async reported a failure");
        // The runtime kept polling while the close ran, which is the whole point:
        // the guard task had to be polled for its guard to drop.
        let _ = runtime.block_on(guard);
        ticker.abort();
        let _ = runtime.block_on(ticker);
        assert!(
            ticks.load(std::sync::atomic::Ordering::Relaxed) > 0,
            "the ticker never ran, so the runtime was never polling and the window \\
             this test exists to arrange was not created"
        );
        drop(engine);
    }

    /// A restored value has to come back exactly as the WAL carried it.
    ///
    /// `put_with_ttl` writes a `TtlInline` payload into the batch, so the value in
    /// the WAL already starts with a kind byte. The restore used to prepend `Inline`
    /// to anything that was not `Inline` or `Tombstone`, which turned a TTL entry
    /// into inline bytes: the TTL was lost and the expiry leaked into the restored
    /// value.
    ///
    /// Tested against `apply_pitr_restore_batch_exact` rather than the restore
    /// planner, which keeps its own model and never prefixes anything.
    #[cfg(target_os = "linux")]
    #[test]
    fn a_restored_ttl_value_keeps_its_kind_prefix() {
        let dir = tempdir().unwrap();
        let engine = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        let expire_at = crate::vlog::compute_expire_at(std::time::Duration::from_secs(3600));
        let batch = crate::pitr::WalBatch {
            commit_ts: 8,
            recorded_at: crate::pitr::RecordedAt { secs: 2, nanos: 0 },
            entries: vec![crate::pitr::WalEntry::Put {
                key: b"ttl-key".to_vec(),
                value: crate::vlog::encode_ttl_value(
                    crate::vlog::KvKind::TtlInline,
                    expire_at,
                    b"ttl-value",
                ),
            }],
        };
        engine.apply_pitr_restore_batch_exact(&batch).unwrap();
        assert_eq!(
            engine.get(b"ttl-key").unwrap().as_deref(),
            Some(b"ttl-value".as_slice()),
            "a TTL entry has to restore as its user value, not as the kind byte and \
             the expiry the restore prepended"
        );
        let _ = engine.close();
    }

    /// A resume that loses the lifecycle to a concurrent disable has to say so. The
    /// install is skipped because the lifecycle left the enabled set while this call
    /// was in flight, so reporting "the runtime is not attached" names a caller
    /// error instead of the transition that actually happened - and it is the one
    /// interleaving where the caller can do nothing about it.
    ///
    /// Arranged, not raced: the barrier parks the resume after its read and before
    /// the install decision, the witness proves the read happened, and the disable
    /// lands while the resume waits.
    #[cfg(target_os = "linux")]
    #[test]
    fn a_resume_that_loses_the_lifecycle_reports_reconciliation_rather_than_a_missing_runtime() {
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let options = LsmStorageOptions {
            enable_wal: true,
            ..LsmStorageOptions::default_for_test()
        };
        let engine = KvEngine::open(dir.path().join("db"), options.clone()).unwrap();
        engine
            .enable_pitr(crate::pitr::api::PitrOptions {
                repository: repository.clone(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval: std::time::Duration::from_secs(3600),
                    max_segment_bytes: 1 << 20,
                    max_unarchived_bytes: 1 << 20,
                    max_source_spool_bytes: 8 << 20,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        engine.put(b"before-disable", b"value").unwrap();

        // Cleared so the resume's own write to it witnesses that it is past the
        // lifecycle read.
        *engine.pitr_repository_path.lock() = None;
        let barrier = engine.pitr_barrier_lock.lock();
        std::thread::scope(|scope| {
            let resume = scope.spawn(|| engine.resume_pitr(repository.clone()));
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
            while engine.pitr_repository_path.lock().is_none() {
                assert!(
                    std::time::Instant::now() < deadline,
                    "the racing resume never read the lifecycle; the window this test \
                     exists to arrange was not created"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
            // The disable that wins: the lifecycle leaves the enabled set and the
            // runtime is detached with it. Both happen while the resume is parked at
            // the barrier, so the resume reads the result of both. The state is the
            // one a clean disable replays - no active segment and no obligations.
            let mut disabled = engine.pitr_manifest_state.lock().clone();
            disabled.mode = crate::pitr::manifest::PitrMode::Disabled;
            disabled.active_segment_id = None;
            disabled.obligations.clear();
            disabled.uncertain_segment_id = None;
            engine.detach_pitr_lifecycle(disabled).unwrap();
            drop(barrier);
            let outcome = resume.join().unwrap().unwrap_or_else(|error| {
                panic!("a resume that lost the lifecycle must not report an error: {error:?}")
            });
            assert!(
                matches!(
                    outcome,
                    crate::pitr::api::PitrResumeOutcome::ReconciliationRequired(_)
                ),
                "expected reconciliation to be required, got {outcome:?}"
            );
        });
        drop(engine);
        let reopened = KvEngine::open(dir.path().join("db"), options).unwrap();
        assert_eq!(
            reopened.get(b"before-disable").unwrap().as_deref(),
            Some(b"value".as_slice())
        );
        let _ = reopened.close();
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_freeze_then_restart_reopens_with_every_key() {
        // A freeze starts a segment WAL that the durable frontier never records -
        // the sealing machinery that would is not part of this layer - so recovery
        // has to reconcile against the WALs on disk. Reading the frontier as the
        // set of recoverable segments refused to open this database at all.
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let db = dir.path().join("db");
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 2 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let engine = KvEngine::open(&db, options.clone()).unwrap();
        enable_pitr_for_test(&engine, &repository, PITR_TEST_ARCHIVE_INTERVAL);
        let value = vec![7u8; 4096];
        for index in 0..700u32 {
            engine.put(&index.to_be_bytes(), &value).unwrap();
        }
        drop(engine);

        let reopened = KvEngine::open(&db, options).unwrap();
        // Layers above this one stop commit admission until PITR is resumed, so
        // resume the way a caller has to before writing again.
        reopened.resume_pitr(&repository).unwrap();
        for index in 0..700u32 {
            assert!(
                reopened.get(&index.to_be_bytes()).unwrap().is_some(),
                "key {index} was lost across the restart"
            );
        }
        // Keep writing past the freeze threshold: the allocator has to account for
        // the segment files the restart recovered, or the first freeze mints one of
        // their names again and fails a write that is already durable.
        for index in 700..1400u32 {
            reopened
                .put(&index.to_be_bytes(), &value)
                .unwrap_or_else(|error| {
                    panic!("write {index} after the restart failed: {error:#}")
                });
        }
        drop(reopened);
    }

    /// A database that enabled PITR, wrote a key, force-froze, and wrote another:
    /// two live memtables, each with its own segment WAL, and a manifest that
    /// records which segment belongs to which.
    #[cfg(target_os = "linux")]
    fn pitr_database_with_two_segments(
        root: &std::path::Path,
        options: &LsmStorageOptions,
    ) -> std::path::PathBuf {
        let parent = crate::backup::open_directory_no_follow(root).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = root.join("repository");
        let db = root.join("db");
        let engine = KvEngine::open(&db, options.clone()).unwrap();
        enable_pitr_for_test(&engine, &repository, std::time::Duration::from_secs(1));
        engine.put(b"first", b"value").unwrap();
        engine
            .inner
            .force_freeze_memtable(&engine.inner.state_lock.lock())
            .unwrap();
        engine.put(b"second", b"value").unwrap();
        drop(engine);

        db
    }

    /// The segment WALs on disk, in mint order.
    #[cfg(target_os = "linux")]
    fn pitr_segment_wals(db: &std::path::Path) -> Vec<(u64, std::path::PathBuf)> {
        let mut segments: Vec<_> = std::fs::read_dir(db)
            .unwrap()
            .filter_map(|entry| entry.ok().map(|entry| entry.path()))
            .filter_map(|path| {
                let name = path.file_name()?.to_str()?;
                let segment_id = name
                    .strip_prefix("pitr-")?
                    .strip_suffix(".wal")?
                    .parse()
                    .ok()?;
                Some((segment_id, path))
            })
            .collect();
        segments.sort_unstable();

        segments
    }

    /// Write a segment WAL above every recorded one and return its id: the crash
    /// window between creating a successor and recording it leaves such a file
    /// behind, empty of records when the crash lands early and holding commits
    /// when it lands late.
    #[cfg(target_os = "linux")]
    fn write_unrecorded_segment(db: &std::path::Path, with_records: bool) -> u64 {
        let (newest, source_path) = pitr_segment_wals(db)
            .pop()
            .expect("a segment WAL to build the unrecorded one from");
        let segment_id = newest + 1;
        let mut source = std::fs::File::open(source_path).unwrap();
        let mut header_bytes = vec![0; crate::pitr::WAL_V5_HEADER_LEN];
        std::io::Read::read_exact(&mut source, &mut header_bytes).unwrap();
        let mut header = crate::pitr::decode_v5_file_header(&header_bytes).unwrap();
        header.segment_id = crate::pitr::SegmentId(segment_id);
        let mut bytes = crate::pitr::encode_v5_file_header(header).unwrap().to_vec();
        if with_records {
            let batch = crate::pitr::WalBatch {
                commit_ts: 1,
                recorded_at: crate::pitr::RecordedAt { secs: 1, nanos: 0 },
                entries: vec![crate::pitr::WalEntry::Put {
                    key: b"unrecorded".to_vec(),
                    value: vec![crate::vlog::KvKind::Inline as u8, b'v'],
                }],
            };
            bytes.extend(
                crate::pitr::encode_v5_batch(&batch, crate::pitr::LIVE_WAL_V5_LIMITS).unwrap(),
            );
        }
        std::fs::write(db.join(format!("pitr-{segment_id:020}.wal")), bytes).unwrap();

        segment_id
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_refuses_a_segment_wal_that_no_memtable_records() {
        // Pairing memtables with segment WALs by order hands a segment the
        // manifest never recorded to the newest memtable that needs one, and
        // that memtable's own segment — the one holding its commits — goes to
        // whichever memtable sits at the offset. The image reproduces as a
        // silent drop of a segment's worth of committed writes. Recording the
        // segment makes the pairing exact, which leaves the unrecorded segment
        // without an owner; because it holds records, opening without it would
        // report a commit log shorter than the one on disk, so it is refused.
        let dir = tempdir().unwrap();
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 64 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let db = pitr_database_with_two_segments(dir.path(), &options);
        write_unrecorded_segment(&db, true);

        let error = KvEngine::open(&db, options)
            .err()
            .expect("a segment WAL holding records that no memtable records must not open");

        assert!(
            format!("{error:#}").contains("recorded for no memtable"),
            "unexpected error: {error:#}"
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_discards_a_recordless_segment_wal_that_no_memtable_records() {
        // The same crash window before the successor takes a write leaves a
        // header and nothing else. There is no commit to lose, and its id has to
        // be mintable again or the next freeze fails on the file being there.
        let dir = tempdir().unwrap();
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 64 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let db = pitr_database_with_two_segments(dir.path(), &options);
        let unrecorded = write_unrecorded_segment(&db, false);

        let reopened = KvEngine::open(&db, options).unwrap();
        assert!(reopened.get(b"first").unwrap().is_some());
        assert!(reopened.get(b"second").unwrap().is_some());
        drop(reopened);
        assert!(
            !db.join(format!("pitr-{unrecorded:020}.wal")).exists(),
            "the recordless segment WAL must be discarded"
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_refuses_an_unrecorded_segment_after_a_snapshot_replaced_the_log() {
        // The log is rewritten as a snapshot once it outgrows
        // `manifest_snapshot_threshold_bytes`, and that rewrite is what the
        // recorded segments have to survive. A snapshot that dropped them would
        // put the next open back on pairing by order, with the same silent loss
        // the records exist to prevent.
        let dir = tempdir().unwrap();
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 64 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let db = pitr_database_with_two_segments(dir.path(), &options);

        let engine = KvEngine::open(
            &db,
            LsmStorageOptions {
                manifest_snapshot_threshold_bytes: 1,
                ..options.clone()
            },
        )
        .unwrap();
        engine
            .inner
            .maybe_snapshot_manifest(&engine.inner.state_lock.lock())
            .unwrap();
        drop(engine);
        assert!(
            !std::fs::read_to_string(db.join("MANIFEST"))
                .unwrap()
                .contains("NewPitrMemtable"),
            "the log has to be replaced by the snapshot for this test to mean anything"
        );

        write_unrecorded_segment(&db, true);
        let error = KvEngine::open(&db, options)
            .err()
            .expect("the recorded segments must survive a snapshot");

        assert!(
            format!("{error:#}").contains("recorded for no memtable"),
            "unexpected error: {error:#}"
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_opens_a_log_that_records_no_segments() {
        // A log written before segments were recorded names its memtables and
        // nothing else. Recovery has to keep pairing those by mint order: the
        // memtables still alive are the newest ones, and their segments are the
        // newest WALs on disk.
        let dir = tempdir().unwrap();
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 64 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let db = pitr_database_with_two_segments(dir.path(), &options);

        let manifest = db.join("MANIFEST");
        let records = std::fs::read_to_string(&manifest).unwrap();
        let mut rewritten = String::new();
        for record in serde_json::Deserializer::from_str(&records).into_iter::<serde_json::Value>()
        {
            let record = record.unwrap();
            let record = match record
                .get("NewPitrMemtable")
                .and_then(|entry| entry.get("id"))
            {
                Some(id) => serde_json::json!({ "NewMemtable": id }),
                None => record,
            };
            rewritten.push_str(&record.to_string());
            rewritten.push('\n');
        }
        std::fs::write(&manifest, rewritten).unwrap();

        let reopened = KvEngine::open(&db, options).unwrap();
        assert!(reopened.get(b"first").unwrap().is_some());
        assert!(reopened.get(b"second").unwrap().is_some());
        drop(reopened);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_freeze_then_restart_keeps_writes_after_a_flush() {
        // The same restart with the frozen memtables flushed first, which leaves
        // only the active memtable to recover. Recovery used to hand it the oldest
        // segment WAL, silently dropping every write made after the freeze.
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let db = dir.path().join("db");
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 2 * 1024 * 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let engine = KvEngine::open(&db, options.clone()).unwrap();
        enable_pitr_for_test(&engine, &repository, PITR_TEST_ARCHIVE_INTERVAL);
        let value = vec![7u8; 4096];
        for index in 0..700u32 {
            engine.put(&index.to_be_bytes(), &value).unwrap();
        }
        while !engine.inner.state.load().imm_memtables.is_empty() {
            engine.inner.force_flush_next_imm_memtable().unwrap();
        }
        engine.put(b"sentinel", b"value").unwrap();
        drop(engine);

        let reopened = KvEngine::open(&db, options).unwrap();
        assert!(
            reopened.get(b"sentinel").unwrap().is_some(),
            "the write made after the freeze was lost across the restart"
        );
        for index in 0..700u32 {
            assert!(
                reopened.get(&index.to_be_bytes()).unwrap().is_some(),
                "key {index} was lost across the restart"
            );
        }
        drop(reopened);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn configured_repository_keeps_interrupted_enable_blocked() {
        let dir = tempdir().unwrap();
        let repository_path = dir.path().join("repository");
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = crate::backup::BackupRepository::open(&repository_path).unwrap();
        let repository_id = repository.ensure_pitr_repository_identity().unwrap();
        drop(repository);
        let engine = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        let mut coordinator = crate::pitr::enable::PitrEnableCoordinator::default();
        coordinator
            .begin_enable_with_identities(
                crate::pitr::enable::PitrEnableRequest {
                    repository_id,
                    config: crate::pitr::manifest::PersistedPitrConfig {
                        archive_interval_ms: 60_000,
                        max_segment_bytes: 1024 * 1024,
                        max_unarchived_bytes: 2 * 1024 * 1024,
                        max_source_spool_bytes: 4 * 1024 * 1024,
                    },
                },
                [7; 16],
                [8; 16],
            )
            .unwrap();
        engine
            .persist_pitr_lifecycle(coordinator.records(), coordinator.state().clone())
            .unwrap();
        engine.close_storage().unwrap();

        let reopened = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                pitr_repository: Some(repository_path),
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        assert_eq!(
            reopened.pitr_manifest_state.lock().mode,
            crate::pitr::manifest::PitrMode::Enabling
        );
        assert_eq!(
            reopened
                .pitr_status(crate::pitr::api::PitrStatusOptions {
                    cursor: None,
                    page_size: crate::pitr::api::MAX_STATUS_PAGE_SIZE,
                })
                .unwrap()
                .recoverable_intervals
                .len(),
            0
        );
        assert!(reopened.put(b"after-enable-recovery", b"value").is_err());
        // An interrupted enable is not a durably closable state; the persisted
        // enable is resumed on the next open instead.
        assert!(reopened.close().is_err());
        reopened.close_storage().unwrap();
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_resumed_interrupted_enable_keeps_allocating_new_segments() {
        // The same crash window as the test above, but resumed rather than left
        // alone. The adopted successor already owns segment 0, so the allocator
        // has to account for it: `resume_pitr` installs no further successor once
        // the active memtable reports `uses_wal_v5`, and a freeze that mints
        // segment 0 again collides with the live segment's file name.
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let db = dir.path().join("db");
        let options = LsmStorageOptions {
            enable_wal: true,
            target_sst_size: 1024,
            ..LsmStorageOptions::default_for_test()
        };
        let engine = KvEngine::open(&db, options.clone()).unwrap();
        // Take the identity the repository already persists: `resume_pitr`
        // rejects a fabricated one.
        let request = engine
            .prepare_pitr_enable_request(&crate::pitr::api::PitrOptions {
                repository: repository.clone(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval: PITR_TEST_ARCHIVE_INTERVAL,
                    max_segment_bytes: 1024 * 1024,
                    max_unarchived_bytes: 4 * 1024 * 1024,
                    max_source_spool_bytes: 8 * 1024 * 1024,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        let mut coordinator = crate::pitr::enable::PitrEnableCoordinator::default();
        coordinator
            .begin_enable_with_identities(request, [2; 16], [3; 16])
            .unwrap();
        engine
            .persist_pitr_lifecycle(coordinator.records(), coordinator.state().clone())
            .unwrap();
        engine
            .inner
            .install_pitr_v5_successor(
                crate::pitr::WalV5Header {
                    wal_format_version: crate::pitr::WAL_V5_VERSION,
                    timeline_id: crate::pitr::TimelineId([2; 16]),
                    archive_epoch_id: crate::pitr::ArchiveEpochId([3; 16]),
                    segment_id: crate::pitr::SegmentId(0),
                    predecessor: crate::pitr::ChainAnchor::Genesis {
                        archive_epoch_id: crate::pitr::ArchiveEpochId([3; 16]),
                    },
                },
                &engine.inner.state_lock.lock(),
            )
            .unwrap();
        // Closing an interrupted enable is reported as an error from the layer
        // that added the PITR-aware close onward; dropping releases the storage
        // on every layer.
        drop(engine);

        let reopened = KvEngine::open(&db, options).unwrap();
        assert!(matches!(
            reopened.resume_pitr(&repository).unwrap(),
            crate::pitr::api::PitrResumeOutcome::Resumed
        ));
        // The allocator has to be past the segment the enable adopted: it is what
        // the next freeze draws from, and at 0 that freeze mints segment 0 again
        // and fails against the live segment's file.
        assert!(
            reopened
                .inner
                .pitr_next_segment_id
                .load(std::sync::atomic::Ordering::Acquire)
                >= 1,
            "the allocator must be past the adopted segment after resume"
        );
        // Writes must keep working; where the memtable crosses the freeze
        // threshold this also allocates the segment above.
        for index in 0..64u8 {
            let key = [b'k', index];
            let value = [b'v'; 64];
            reopened
                .put(&key, &value)
                .unwrap_or_else(|error| panic!("write {index} after resume failed: {error:#}"));
        }
        reopened.close().unwrap();
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn pitr_enable_preflight_binds_repository_identity() {
        let dir = tempdir().unwrap();
        let repository = dir.path().join("repository");
        let engine = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        let request = engine
            .prepare_pitr_enable_request(&crate::pitr::api::PitrOptions {
                repository: repository.clone(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval: std::time::Duration::from_secs(1),
                    max_segment_bytes: 8192,
                    max_unarchived_bytes: 8192,
                    max_source_spool_bytes: 16384,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        // The preflight must carry the identity that is already persisted in the repository, not a
        // freshly drawn one; a non-zero check alone would not notice the difference.
        let persisted = crate::backup::BackupRepository::open(&repository)
            .unwrap()
            .ensure_pitr_repository_identity()
            .unwrap();
        assert_eq!(request.repository_id, persisted);
        assert_ne!(request.repository_id, [0; 16]);
        assert_eq!(request.config.archive_interval_ms, 1000);
        assert!(repository.is_dir());
        engine.close().unwrap();
    }

    /// A disable whose marker write cannot be settled has to leave commit admission
    /// closed.
    ///
    /// `disable_pitr_allow_gap` stops admission before it persists the coverage gap.
    /// When that publication's outcome is unknowable - the batch may be durable
    /// without its fsync - reopening would let the epoch accept writes into a
    /// segment the durable state already describes as sealed, so only a disable that
    /// landed cleanly reopens. `resume_pitr` is the way to settle the rest.
    ///
    /// The other arm - a plain error, which proves the batch did not land - is the
    /// one that reopens, and `c368b580` is what made it do so; this test pins the
    /// arm that must stay closed, which is the half a future edit is more likely to
    /// get wrong by reopening both.
    #[cfg(target_os = "linux")]
    #[test]
    fn an_uncertain_disable_publication_keeps_commit_admission_closed() {
        let dir = tempdir().unwrap();
        let parent = crate::backup::open_directory_no_follow(dir.path()).unwrap();
        crate::backup::bootstrap_repository(&parent, "repository").unwrap();
        let repository = dir.path().join("repository");
        let engine = KvEngine::open(
            dir.path().join("db"),
            LsmStorageOptions {
                enable_wal: true,
                ..LsmStorageOptions::default_for_test()
            },
        )
        .unwrap();
        engine
            .enable_pitr(crate::pitr::api::PitrOptions {
                repository: repository.clone(),
                config: crate::pitr::api::PersistedPitrConfig {
                    archive_interval: std::time::Duration::from_secs(3600),
                    max_segment_bytes: 1 << 20,
                    max_unarchived_bytes: 1 << 20,
                    max_source_spool_bytes: 8 << 20,
                },
                runtime: crate::pitr::api::PitrRuntimeOptions::default(),
            })
            .unwrap();
        engine.put(b"before-disable", b"value").unwrap();

        crate::manifest::set_manifest_sync_failure(&dir.path().join("db/MANIFEST"));
        let outcome = engine.disable_pitr_allow_gap().unwrap();
        assert!(
            matches!(
                outcome,
                crate::pitr::api::DisablePitrOutcome::SourceManifestPublishedButNotDurable { .. }
                    | crate::pitr::api::DisablePitrOutcome::PublicationUnknown { .. }
            ),
            "expected an unsettleable disable publication, got {outcome:?}"
        );
        assert!(
            !engine
                .inner
                .mvcc
                .as_ref()
                .unwrap()
                .commit_admission_is_open(),
            "an unsettleable disable publication has to leave admission closed"
        );
        // Writes are refused rather than accepted into a segment the durable state
        // already describes as sealed - that is the property the closed admission
        // buys.
        assert!(engine.put(b"after-disable", b"value").is_err());
        engine.close_storage().unwrap();
    }

